// ============================================================
// 语言切换按钮组
// ============================================================

import { t, getCurrentLang, setLanguage, getSupportedLangs } from '@/i18n'
import type { SupportedLang } from '@/i18n/types'
import type { I18nKeys } from '@/i18n/types'
import { createElement } from '@/utils/dom'

type LangChangeCallback = () => void

export function createLangSwitcher(onChange?: LangChangeCallback): HTMLElement {
  const container = createElement('div', { className: 'lang-switcher' })

  const langLabels: Record<SupportedLang, keyof I18nKeys> = {
    zh: 'langZh',
    en: 'langEn',
    ja: 'langJa',
    ko: 'langKo',
    th: 'langTh',
    id: 'langId',
  }

  const current = getCurrentLang()

  for (const lang of getSupportedLangs()) {
    const label = t(langLabels[lang])
    const btn = createElement('button', {
      className: `lang-btn ${lang === current ? 'active' : ''}`,
      textContent: label,
      onClick: () => {
        if (lang !== current) {
          setLanguage(lang)
          onChange?.()
        }
      },
    })
    container.appendChild(btn)
  }

  return container
}
