import type { ModeConfig, EmotionCategory } from '@/types'
import { positiveMode } from './positive-mode'
import { negativeMode } from './negative-mode'

export function createModeConfig(category: EmotionCategory): ModeConfig {
  switch (category) {
    case 'positive':
    case 'neutral':
      return { ...positiveMode }
    case 'negative':
      return { ...negativeMode }
  }
}
