// ============================================================
// 治愈完成页面（负面模式专属）
// ============================================================

import { t } from '@/i18n'
import { createElement, clearElement, getAppContainer } from '@/utils/dom'
import { stateMachine } from '@/state/machine'
import { GameState } from '@/types'
import { track } from '@/services/analytics'
import './healed.css'

export function renderHealed(): void {
  const app = getAppContainer()
  clearElement(app)

  const ctx = stateMachine.context
  const page = createElement('main', { className: 'page healed-page', attrs: { role: 'main', 'aria-label': '治愈完成页面' } })

  // 暖光绽放背景
  const bloom = createElement('div', { className: 'heal-bloom' })

  // 主标题
  const title = createElement('h1', {
    className: 'healed-title',
    textContent: t('negativeHealTitle'),
  })

  // 副标题
  const subtitle = createElement('p', {
    className: 'healed-subtitle',
    textContent: t('negativeHealSubtitle'),
  })

  // 蛇的最终表情
  const finalEmoji = createElement('div', {
    className: 'healed-emoji',
    textContent: '🌱',
  })

  // 统计信息
  const stats = createElement('div', { className: 'healed-stats' })
  if (ctx.score !== undefined) {
    const scoreLine = createElement('p', {
      className: 'healed-stat',
      textContent: `${t('negativeCollected')} ${ctx.score} 个情绪碎片`,
    })
    stats.appendChild(scoreLine)
  }
  if (ctx.healLevel !== undefined) {
    const levelLine = createElement('p', {
      className: 'healed-stat',
      textContent: `${t('negativeLevelUp')} Lv.${ctx.healLevel + 1}/5`,
    })
    stats.appendChild(levelLine)
  }

  // 完成文案
  const doneText = createElement('p', {
    className: 'healed-done',
    textContent: t('negativeHealDone'),
  })

  // 继续按钮
  const continueBtn = createElement('button', {
    className: 'btn healed-btn',
    textContent: t('assessTitle'), // "现在感觉怎么样？"
    onClick: () => {
      stateMachine.transition(GameState.ASSESS)
    },
  })

  page.append(bloom, finalEmoji, title, subtitle, stats, doneText, continueBtn)
  app.appendChild(page)

  track('page_view', { page_name: 'healed' })
}
