// ============================================================
// localStorage 封装 + 禅意句子
// ============================================================

import { getCurrentLang } from '@/i18n'
import type { SupportedLang } from '@/i18n/types'
import zhQuotes from '@/i18n/quotes/zh.json'
import enQuotes from '@/i18n/quotes/en.json'
import jaQuotes from '@/i18n/quotes/ja.json'
import koQuotes from '@/i18n/quotes/ko.json'
import thQuotes from '@/i18n/quotes/th.json'
import idQuotes from '@/i18n/quotes/id.json'

const quoteMap: Record<SupportedLang, string[]> = {
  zh: zhQuotes,
  en: enQuotes,
  ja: jaQuotes,
  ko: koQuotes,
  th: thQuotes,
  id: idQuotes,
}

// ---- 安全存储封装 ----

function safeStorageGet(storage: Storage | null, key: string): string | null {
  try {
    return storage?.getItem(key) ?? null
  } catch {
    return null
  }
}

function safeStorageSet(storage: Storage | null, key: string, value: string): void {
  try {
    storage?.setItem(key, value)
  } catch {
    // 隐私模式等情况静默失败
  }
}

function getLocalStorage(): Storage | null {
  if (typeof localStorage !== 'undefined') return localStorage
  return null
}

function getSessionStorage(): Storage | null {
  if (typeof sessionStorage !== 'undefined') return sessionStorage
  return null
}

/** 获取随机禅意句子 */
export function getRandomQuote(): string {
  const lang = getCurrentLang()
  const quotes = quoteMap[lang] || quoteMap.zh
  const index = Math.floor(Math.random() * quotes.length)
  return quotes[index]
}

/** 生成 UUID（兼容不支持 crypto.randomUUID 的环境） */
function generateUUID(): string {
  // 优先使用 crypto.randomUUID
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID()
  }
  // 降级：使用 crypto.getRandomValues
  try {
    const bytes = new Uint8Array(16)
    crypto.getRandomValues(bytes)
    bytes[6] = (bytes[6] & 0x0f) | 0x40 // version 4
    bytes[8] = (bytes[8] & 0x3f) | 0x80 // variant 10
    const hex = Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')
    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
  } catch {
    // 最终降级：Math.random
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
      const r = (Math.random() * 16) | 0
      const v = c === 'x' ? r : (r & 0x3) | 0x8
      return v.toString(16)
    })
  }
}

/** 获取 session ID */
export function getSessionId(): string {
  const storage = getSessionStorage()
  let sid = safeStorageGet(storage, 'tui-session-id')
  if (!sid) {
    sid = generateUUID()
    safeStorageSet(storage, 'tui-session-id', sid)
  }
  return sid
}
