// ============================================================
// 游戏循环 (requestAnimationFrame + 固定时间步长)
// ============================================================

export type UpdateFn = (deltaTime: number) => void
export type RenderFn = (interpolation: number) => void

export class GameLoop {
  private rafId: number | null = null
  private lastTime = 0
  private accumulator = 0
  private step: number // ms per logic step
  private updateFn: UpdateFn
  private renderFn: RenderFn
  private running = false

  constructor(step: number, update: UpdateFn, render: RenderFn) {
    this.step = step
    this.updateFn = update
    this.renderFn = render
  }

  /** 更新步进间隔（用于难度变化） */
  setStep(newStep: number): void {
    this.step = newStep
  }

  start(): void {
    if (this.running) return
    this.running = true
    this.lastTime = performance.now()
    this.accumulator = 0
    this.loop(this.lastTime)
  }

  stop(): void {
    this.running = false
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId)
      this.rafId = null
    }
  }

  private loop = (now: number): void => {
    if (!this.running) return

    const elapsed = now - this.lastTime
    this.lastTime = now
    this.accumulator += elapsed

    // 固定时间步长更新
    while (this.accumulator >= this.step) {
      this.updateFn(this.step)
      this.accumulator -= this.step
    }

    // 渲染（带插值）
    const interpolation = this.accumulator / this.step
    this.renderFn(interpolation)

    this.rafId = requestAnimationFrame(this.loop)
  }
}
