const siteBaseUrl = 'https://tui.example.com' // TODO: 替换为实际域名

/** 安全读取 localStorage */
function safeGetItem(key: string): string | null {
  try {
    return localStorage.getItem(key)
  } catch {
    return null
  }
}

/** 安全写入 localStorage */
function safeSetItem(key: string, value: string): void {
  try {
    localStorage.setItem(key, value)
  } catch {
    // 隐私模式等情况静默失败
  }
}

/** 检测浏览器语言 */
function detectLanguage(): SupportedLang {
  // 1. 优先读 localStorage
  const saved = safeGetItem('tui-lang') as SupportedLang | null
  if (saved && (SUPPORTED_LANGS as readonly string[]).includes(saved)) {
    return saved
  }
  // 2. 自动检测浏览器语言
  const browserLang = navigator.language.split('-')[0]
  if ((SUPPORTED_LANGS as readonly string[]).includes(browserLang)) {
    return browserLang as SupportedLang
  }
  // 3. 默认中文
  return 'zh'
}

/** 初始化语言 */
export function initI18n(): void {
  currentLang = detectLanguage()
  updateSEOMeta() // 初始化 SEO 元数据
}

/** 获取当前语言 */
export function getCurrentLang(): SupportedLang {
  return currentLang
}

/** 设置语言 */
export function setLanguage(lang: SupportedLang): void {
  currentLang = lang
  safeSetItem('tui-lang', lang)
  updateSEOMeta() // 切换语言时更新 SEO 元数据
}

/** 翻译函数 */
export function t(key: keyof I18nKeys): string {
  return translations[currentLang][key]
}

/** 获取所有支持的语言列表 */
export function getSupportedLangs(): readonly SupportedLang[] {
  return SUPPORTED_LANGS
}

// ============================================================
// SEO 元数据更新
// ============================================================

/** 更新页面的 SEO 元标签（标题、描述、OG、hreflang） */
export function updateSEOMeta(pageTitle?: string): void {
  const lang = currentLang
  const baseTitle = seoTitles[lang]

  // 完整标题
  const fullTitle = pageTitle ? `${pageTitle} - ${baseTitle}` : baseTitle
  document.title = fullTitle

  // Description
  updateMetaTag('description', seoDescriptions[lang])

  // OG tags
  updateMetaTag('og:title', fullTitle, 'property')
  updateMetaTag('og:description', seoDescriptions[lang], 'property')
  updateMetaTag('og:locale', getOgLocale(lang), 'property')

  // Twitter
  updateMetaTag('twitter:title', fullTitle, 'name')
  updateMetaTag('twitter:description', seoDescriptions[lang], 'name')

  // hreflang
  updateHreflang(lang)

  // HTML lang 属性
  document.documentElement.lang = getHtmlLang(lang)
}

/** 更新单个 meta 标签 */
function updateMetaTag(name: string, content: string, attr: 'name' | 'property' = 'name'): void {
  let tag = document.querySelector(`meta[${attr}="${name}"]`)
  if (!tag) {
    tag = document.createElement('meta')
    tag.setAttribute(attr, name)
    document.head.appendChild(tag)
  }
  tag.setAttribute('content', content)
}

/** 更新 hreflang 标签 */
function updateHreflang(current: SupportedLang): void {
  // 移除旧的 hreflang
  document.querySelectorAll('link[rel="alternate"][hreflang]').forEach(el => el.remove())

  // 添加新的
  SUPPORTED_LANGS.forEach(lang => {
    const link = document.createElement('link')
    link.setAttribute('rel', 'alternate')
    link.setAttribute('hreflang', lang)
    link.setAttribute('href', `${siteBaseUrl}/?lang=${lang}`)
    document.head.appendChild(link)
  })

  // x-default
  const xDefault = document.createElement('link')
  xDefault.setAttribute('rel', 'alternate')
  xDefault.setAttribute('hreflang', 'x-default')
  xDefault.setAttribute('href', siteBaseUrl + '/')
  document.head.appendChild(xDefault)
}

/** 语言代码转换（用于 og:locale） */
function getOgLocale(lang: SupportedLang): string {
  const map: Record<SupportedLang, string> = {
    zh: 'zh_CN',
    en: 'en_US',
    ja: 'ja_JP',
    ko: 'ko_KR',
    th: 'th_TH',
    id: 'id_ID',
  }
  return map[lang] || 'en_US'
}

/** 语言代码转换（用于 html lang 属性） */
function getHtmlLang(lang: SupportedLang): string {
  const map: Record<SupportedLang, string> = {
    zh: 'zh-CN',
    en: 'en',
    ja: 'ja',
    ko: 'ko',
    th: 'th',
    id: 'id',
  }
  return map[lang] || 'en'
}
