// ============================================================
// 首页模块
// ============================================================

import { t } from '@/i18n'
import { createElement, clearElement, getAppContainer } from '@/utils/dom'
import { MAX_INPUT_LENGTH } from '@/utils/constants'
import { stateMachine } from '@/state/machine'
import { GameState } from '@/types'
import { createLangSwitcher } from '@/components/lang-switcher'
import { showEmergencyHelp } from '@/components/emergency-help'
import { track } from '@/services/analytics'
import { getRandomQuote } from '@/services/storage'
import './home.css'

export function renderHome(): void {
  const app = getAppContainer()
  clearElement(app)

  const page = createElement('main', { className: 'page home-page', attrs: { role: 'main', 'aria-label': '首页' } })

  // 标题
  const title = createElement('h1', {
    className: 'home-title',
    textContent: t('title'),
  })

  // 标语
  const tagline = createElement('p', {
    className: 'home-tagline',
    textContent: t('tagline'),
  })

  // 情绪输入表单
  const inputGroup = createElement('form', {
    className: 'input-group',
    attrs: { 'aria-label': '情绪输入表单' },
    onClick: (e) => { e.preventDefault() }, // 阻止表单默认提交
  })
  const textarea = createElement('textarea', {
    className: 'emotion-input',
    attrs: {
      placeholder: t('placeholder'),
      maxlength: String(MAX_INPUT_LENGTH),
      rows: '3',
      'aria-label': t('placeholder'),
    },
  }) as HTMLTextAreaElement

  const submitBtn = createElement('button', {
    className: 'btn submit-btn',
    textContent: t('submit'),
    attrs: { 'aria-label': t('submit') },
    onClick: (e) => {
      e.preventDefault()
      const text = textarea.value.trim()
      if (!text) return
      stateMachine.updateContext({ emotionText: text })
      stateMachine.transition(GameState.LOADING)
      track('emotion_input', { text_length: text.length })
    },
  })

  inputGroup.append(textarea, submitBtn)

  // 底部区域
  const bottom = createElement('footer', { className: 'home-bottom', attrs: { role: 'contentinfo' } })

  // 禅意短句
  const quote = getRandomQuote()
  const quoteEl = createElement('p', {
    className: 'zen-quote',
    textContent: quote,
  })

  // 紧急帮助
  const emergencyBtn = createElement('button', {
    className: 'emergency-entry',
    textContent: t('emergencyEntry'),
    attrs: { 'aria-label': t('emergencyEntry') },
    onClick: showEmergencyHelp,
  })

  bottom.append(quoteEl, emergencyBtn)

  // 语言切换
  const langSwitcher = createLangSwitcher(() => {
    renderHome() // 重新渲染首页
  })

  page.append(title, tagline, inputGroup, bottom, langSwitcher)
  app.appendChild(page)

  track('page_view', { page_name: 'home' })
}
