// ============================================================
// Emoji 渲染器 → 委托给 ExpressionRenderer v1.5
// 保持向后兼容：所有调用 emojiRenderer.draw() 的代码自动使用原创表情
// ============================================================

import { expressionRenderer } from '@/expressions/expression-renderer'

/** Emoji 渲染器接口 */
export interface EmojiRenderer {
  draw(ctx: CanvasRenderingContext2D, emoji: string, x: number, y: number, size: number): void
}

/** 原创表情渲染器（v1.5） — 替代原生 emoji */
class ExpressionBasedRenderer implements EmojiRenderer {
  draw(ctx: CanvasRenderingContext2D, emoji: string, x: number, y: number, size: number): void {
    expressionRenderer.drawById(ctx, emoji, x, y, size)
  }
}

/** 单例 */
export const emojiRenderer = new ExpressionBasedRenderer()
