// ============================================================
// 确认界面模块
// ============================================================

import { t } from '@/i18n'
import { createElement, clearElement, getAppContainer } from '@/utils/dom'
import { stateMachine } from '@/state/machine'
import { GameState, type EmotionCategory } from '@/types'
import { judgeEmotionWithTimeout } from '@/services/ai-service'
import { track } from '@/services/analytics'
import './confirm.css'

let selectedCategory: EmotionCategory | null = null

export function renderConfirm(): void {
  const app = getAppContainer()
  clearElement(app)
  selectedCategory = null

  const page = createElement('main', { className: 'page confirm-page', attrs: { role: 'main', 'aria-label': '情绪确认页面' } })
  const ctx = stateMachine.context
  const aiResult = ctx.aiResult

  if (aiResult) {
    // 正常路径：显示 AI 理解文案
    const understanding = createElement('section', { className: 'ai-understanding', attrs: { 'aria-label': 'AI 情绪分析结果' } })
    const label = createElement('p', {
      className: 'ai-label',
      textContent: t('aiUnderstands'),
    })
    const text = createElement('p', {
      className: 'ai-text',
      textContent: aiResult.understanding,
    })
    const category = createElement('div', {
      className: `ai-category ${aiResult.category}`,
      textContent: getCategoryLabel(aiResult.category),
    })
    understanding.append(label, text, category)
    page.appendChild(understanding)
    selectedCategory = aiResult.category
  } else {
    // 超时路径：直接选择
    const chooseLabel = createElement('p', {
      className: 'choose-label',
      textContent: t('chooseEmotion'),
    })
    page.appendChild(chooseLabel)
  }

  // 三选项
  const options = createElement('div', {
    className: 'emotion-options',
    attrs: { role: 'radiogroup', 'aria-label': t('chooseEmotion') },
  })
  const categories: EmotionCategory[] = ['positive', 'neutral', 'negative']
  const labels: Record<EmotionCategory, string> = {
    positive: t('optionPositive'),
    neutral: t('optionNeutral'),
    negative: t('optionNegative'),
  }

  for (const cat of categories) {
    const btn = createElement('button', {
      className: `emotion-option ${selectedCategory === cat ? 'selected' : ''}`,
      textContent: labels[cat],
      attrs: {
        role: 'radio',
        'aria-checked': selectedCategory === cat ? 'true' : 'false',
        'aria-label': labels[cat],
      },
      onClick: () => {
        selectedCategory = cat
        // 更新选中状态
        options.querySelectorAll('.emotion-option').forEach(el => el.classList.remove('selected'))
        btn.classList.add('selected')
      },
    })
    options.appendChild(btn)
  }

  page.appendChild(options)

  // 确认按钮
  const confirmBtn = createElement('button', {
    className: 'btn btn-primary confirm-btn',
    textContent: t('confirmEnter'),
    onClick: () => {
      if (!selectedCategory) return

      const gameMode = selectedCategory === 'negative' ? 'negative' : 'positive'
      stateMachine.updateContext({
        finalCategory: selectedCategory,
        gameMode,
      })

      track('emotion_confirm', {
        ai_category: aiResult?.category ?? null,
        final_category: selectedCategory,
        is_corrected: aiResult ? aiResult.category !== selectedCategory : false,
      })

      stateMachine.transition(GameState.SOUND)
    },
  })

  page.appendChild(confirmBtn)
  app.appendChild(page)

  track('page_view', { page_name: 'confirm' })
}

function getCategoryLabel(category: EmotionCategory): string {
  switch (category) {
    case 'positive': return t('optionPositive')
    case 'neutral': return t('optionNeutral')
    case 'negative': return t('optionNegative')
  }
}

/** Loading 页面渲染 */
export async function renderLoading(): Promise<void> {
  const app = getAppContainer()
  clearElement(app)

  const page = createElement('main', { className: 'page loading-page', attrs: { role: 'main', 'aria-label': '加载中' } })

  const dots = createElement('div', { className: 'loading-dots' })
  dots.appendChild(createElement('span'))
  dots.appendChild(createElement('span'))
  dots.appendChild(createElement('span'))

  const text = createElement('p', {
    className: 'loading-text',
    textContent: t('loadingText'),
  })

  page.append(dots, text)
  app.appendChild(page)

  // 调用 AI 判断
  const ctx = stateMachine.context
  const result = await judgeEmotionWithTimeout(ctx.emotionText!, 'zh')
  stateMachine.updateContext({ aiResult: result })
  stateMachine.transition(GameState.CONFIRM)
}
