// ============================================================
// 紧急帮助弹窗
// ============================================================

import { t } from '@/i18n'
import { createElement } from '@/utils/dom'

let overlay: HTMLElement | null = null

export function showEmergencyHelp(): void {
  if (overlay) return

  overlay = createElement('div', {
    className: 'overlay',
    onClick: (e) => {
      if (e.target === overlay) closeEmergencyHelp()
    },
  })

  const modal = createElement('div', { className: 'modal' })

  const title = createElement('h2', { textContent: t('emergencyTitle') })
  const desc = createElement('p', { textContent: t('emergencyDesc') })

  const hotlines = createElement('div', { className: 'emergency-hotlines' })
  const lines = [
    t('emergencyHotline1'),
    t('emergencyHotline2'),
    t('emergencyHotline3'),
    t('emergencyHotline4'),
  ]
  for (const line of lines) {
    hotlines.appendChild(
      createElement('p', {
        textContent: line,
        className: 'hotline-item',
      })
    )
  }

  const closeBtn = createElement('button', {
    className: 'btn btn-primary',
    textContent: t('emergencyClose'),
    onClick: closeEmergencyHelp,
  })

  modal.append(title, desc, hotlines, closeBtn)
  overlay.appendChild(modal)
  document.body.appendChild(overlay)
}

export function closeEmergencyHelp(): void {
  if (overlay) {
    overlay.remove()
    overlay = null
  }
}
