// ============================================================
// 情绪自评页面
// ============================================================

import { t } from '@/i18n'
import { createElement, clearElement, getAppContainer } from '@/utils/dom'
import { stateMachine } from '@/state/machine'
import { GameState } from '@/types'
import { track } from '@/services/analytics'
import './assess.css'

const ASSESS_OPTIONS = [
  { value: 1, emoji: '😢', key: 'assessLow' as const },
  { value: 2, emoji: '😐', key: 'assessLowMid' as const },
  { value: 3, emoji: '🙂', key: 'assessMid' as const },
  { value: 4, emoji: '😊', key: 'assessHigh' as const },
]

export function renderAssess(): void {
  const app = getAppContainer()
  clearElement(app)

  const page = createElement('main', { className: 'page assess-page', attrs: { role: 'main', 'aria-label': '情绪自评页面' } })

  // 标题
  const title = createElement('h2', {
    className: 'assess-title',
    textContent: t('assessTitle'),
  })

  // 选项容器
  const optionsContainer = createElement('div', {
    className: 'assess-options',
    attrs: { role: 'radiogroup', 'aria-label': t('assessTitle') },
  })

  for (const option of ASSESS_OPTIONS) {
    const btn = createElement('button', {
      className: 'assess-option-btn',
      attrs: {
        role: 'radio',
        'aria-checked': 'false',
        'aria-label': t(option.key),
      },
      onClick: () => onSelect(option.value, optionsContainer),
    })
    const emoji = createElement('span', {
      className: 'assess-option-emoji',
      textContent: option.emoji,
    })
    const label = createElement('span', {
      className: 'assess-option-label',
      textContent: t(option.key),
    })
    btn.append(emoji, label)
    optionsContainer.appendChild(btn)
  }

  // 跳过
  const skipBtn = createElement('button', {
    className: 'assess-skip',
    textContent: t('assessSkip'),
    onClick: onSkip,
  })

  page.append(title, optionsContainer, skipBtn)
  app.appendChild(page)

  track('page_view', { page_name: 'assess' })
}

function onSelect(value: number, container: HTMLElement): void {
  // 禁用所有按钮
  const buttons = container.querySelectorAll('.assess-option-btn')
  buttons.forEach(btn => {
    (btn as HTMLButtonElement).disabled = true
  })

  // 高亮选中项
  const selectedBtn = buttons[value - 1] as HTMLElement
  if (selectedBtn) {
    selectedBtn.classList.add('assess-selected')
  }

  // 显示感谢语
  const thanksKey = value <= 1 ? 'assessThanksLow'
    : value <= 2 ? 'assessThanksMid'
    : 'assessThanksHigh'
  const thanksText = t(thanksKey as 'assessThanksLow')

  const thanksEl = createElement('p', {
    className: 'assess-thanks',
    textContent: thanksText,
  })
  container.parentElement?.insertBefore(thanksEl, container.nextSibling)

  stateMachine.updateContext({ afterEmotion: value })

  track('self_assessment', {
    before_emotion: stateMachine.context.beforeEmotion,
    after_emotion: value,
  })

  // 延迟返回首页
  setTimeout(() => {
    stateMachine.transition(GameState.IDLE)
  }, 2000)
}

function onSkip(): void {
  stateMachine.updateContext({ afterEmotion: undefined })

  track('self_assessment', {
    before_emotion: stateMachine.context.beforeEmotion,
    after_emotion: null,
    skipped: true,
  })

  stateMachine.forceTransition(GameState.IDLE)
}
