// ============================================================
// 食物生成与管理
// ============================================================

import type { Point, Segment } from '@/types'

export class FoodManager {
  gridWidth: number
  gridHeight: number
  currentFood: Point | null = null
  currentEmoji: string = ''

  constructor(gridWidth: number, gridHeight: number) {
    this.gridWidth = gridWidth
    this.gridHeight = gridHeight
  }

  /** 更新网格尺寸 */
  resize(width: number, height: number): void {
    this.gridWidth = width
    this.gridHeight = height
  }

  /** 生成新食物（不与蛇身重叠） */
  spawn(foodPool: string[], snakeSegments: Segment[]): void {
    const occupied = new Set<string>()
    for (const seg of snakeSegments) {
      occupied.add(`${seg.x},${seg.y}`)
    }

    // 找到所有空位
    const available: Point[] = []
    for (let x = 0; x < this.gridWidth; x++) {
      for (let y = 0; y < this.gridHeight; y++) {
        if (!occupied.has(`${x},${y}`)) {
          available.push({ x, y })
        }
      }
    }

    if (available.length === 0) return // 没有空位

    // 随机选一个位置
    const pos = available[Math.floor(Math.random() * available.length)]
    this.currentFood = pos
    this.currentEmoji = foodPool[Math.floor(Math.random() * foodPool.length)]
  }

  /** 检查是否吃到食物 */
  checkEat(headX: number, headY: number): boolean {
    return this.currentFood !== null &&
      this.currentFood.x === headX &&
      this.currentFood.y === headY
  }
}
