// ============================================================
// 统计数据服务
// ============================================================

export interface StatsSummary {
  totalPV: number
  totalUV: number
  totalGames: number
  healedRate: number
  avgHealLevel: number
  languages: Record<string, number>
  pages: Record<string, number>
  emotions: Record<string, number>
}

export interface DailyStats {
  date: string
  pv: number
  uv: number
  games: number
  healed: number
}

const API_BASE = '/api/stats'

/** 获取统计总览 */
export async function fetchStatsSummary(token?: string): Promise<StatsSummary> {
  const headers: Record<string, string> = {}
  if (token) {
    headers['Authorization'] = `Bearer ${token}`
  }
  const res = await fetch(`${API_BASE}/summary`, { headers })
  if (!res.ok) throw new Error(`Failed to fetch stats: ${res.status}`)
  return res.json()
}

/** 获取每日趋势 */
export async function fetchDailyStats(days = 7, token?: string): Promise<DailyStats[]> {
  const headers: Record<string, string> = {}
  if (token) {
    headers['Authorization'] = `Bearer ${token}`
  }
  const res = await fetch(`${API_BASE}/daily?days=${days}`, { headers })
  if (!res.ok) throw new Error(`Failed to fetch daily stats: ${res.status}`)
  return res.json()
}

/** 保存 admin token 到本地 */
export function saveAdminToken(token: string): void {
  localStorage.setItem('tui_admin_token', token)
}

/** 获取本地保存的 admin token */
export function getAdminToken(): string | null {
  return localStorage.getItem('tui_admin_token')
}

/** 清除 admin token */
export function clearAdminToken(): void {
  localStorage.removeItem('tui_admin_token')
}
