// ============================================================
// App 控制器 — 状态机驱动的页面路由
// ============================================================

import { GameState } from '@/types'
import { stateMachine } from '@/state/machine'
import { renderHome } from '@/pages/home'
import { renderLoading, renderConfirm } from '@/pages/confirm'
import { renderSoundSelect } from '@/pages/sound-select'
import { renderGame, destroyGame } from '@/pages/game'
import { renderAssess } from '@/pages/assess'
import { renderHealed } from '@/pages/healed'
import { renderNotFound } from '@/pages/not-found'
import { track } from '@/services/analytics'
import { updateSEOMeta } from '@/i18n'

/** 各状态对应的页面标题（会自动加上站点后缀） */
const statePageTitles: Partial<Record<GameState, string>> = {
  [GameState.IDLE]: '', // 首页用默认标题
  [GameState.LOADING]: '正在感受你的心情',
  [GameState.CONFIRM]: '确认情绪状态',
  [GameState.SOUND]: '声音设置',
  [GameState.PLAYING]: '游戏进行中',
  [GameState.PAUSED]: '游戏暂停',
  [GameState.HEALED]: '你做到了',
  [GameState.ASSESS]: '心情评估',
}

/** 初始化 App，注册状态监听 */
export function initApp(): void {
  stateMachine.on((state, prev, ctx) => {
    track('state_transition', { from: prev, to: state })

    // 更新 SEO 元数据（页面标题等）
    const pageTitle = statePageTitles[state]
    updateSEOMeta(pageTitle || undefined)

    switch (state) {
      case GameState.IDLE:
        renderHome()
        break

      case GameState.LOADING:
        renderLoading()
        break

      case GameState.CONFIRM:
        renderConfirm()
        break

      case GameState.SOUND:
        renderSoundSelect()
        break

      case GameState.PLAYING:
        renderGame()
        break

      case GameState.FAILED:
        // 失败后直接进自评
        stateMachine.transition(GameState.ASSESS)
        break

      case GameState.HEALED:
        renderHealed()
        break

      case GameState.ASSESS:
        renderAssess()
        break

      default:
        console.warn(`[App] Unhandled state: ${state}`)
    }
  })

  // 初始渲染首页
  renderHome()

  // 处理 hash 路由（用于直接访问特定页面）
  handleHashRoute()
  window.addEventListener('hashchange', handleHashRoute)
}

/** 处理 hash 路由 */
function handleHashRoute(): void {
  const hash = window.location.hash.replace(/^#\/?/, '').toLowerCase()

  if (!hash) {
    // 空 hash，回到首页
    if (stateMachine.state !== GameState.IDLE) {
      stateMachine.transition(GameState.IDLE)
    }
    return
  }

  // 统计面板
  if (hash === 'stats' || hash === 'statistics') {
    // 动态加载统计页面
    import('@/pages/stats').then(module => {
      module.renderStats()
    }).catch(err => {
      console.error('Failed to load stats page:', err)
      renderNotFound()
    })
    return
  }

  // 未知路由 → 404
  renderNotFound()
}
