export type SupportedLang = 'zh' | 'en' | 'ja' | 'ko' | 'th' | 'id'

export const SUPPORTED_LANGS: readonly SupportedLang[] = ['zh', 'en', 'ja', 'ko', 'th', 'id'] as const
