// ============================================================
// 全局类型定义
// ============================================================

/** 游戏状态枚举 */
export enum GameState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  CONFIRM = 'CONFIRM',
  SOUND = 'SOUND',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  FAILED = 'FAILED',
  HEALED = 'HEALED',
  ASSESS = 'ASSESS',
}

/** 情绪分类 */
export type EmotionCategory = 'positive' | 'neutral' | 'negative'

/** AI 判断结果 */
export interface EmotionResult {
  category: EmotionCategory
  understanding: string
  latency_ms: number
  from_cache: boolean
}

/** 游戏上下文（跨状态传递数据） */
export interface GameContext {
  emotionText?: string
  aiResult?: EmotionResult | null
  finalCategory?: EmotionCategory
  soundEnabled?: boolean
  gameMode?: 'positive' | 'negative'
  score?: number
  healProgress?: number
  healLevel?: number
  beforeEmotion?: number
  afterEmotion?: number
  gameStartTime?: number
}

/** 蛇节点 */
export interface Segment {
  x: number
  y: number
  emoji: string
}

/** 方向 */
export type Direction = 'up' | 'down' | 'left' | 'right'

/** 坐标 */
export interface Point {
  x: number
  y: number
}

/** 颜色渐变 */
export interface GradientColors {
  from: string
  to: string
}

/** 模式配置 */
export interface ModeConfig {
  type: 'positive' | 'negative'
  backgrounds: GradientColors[]
  gridColor: string
  snakeEmojis: string[]
  foodPools: string[][]
  failEmojis: string[]
  initialLength: number
  initialSpeed: number
  minSpeed: number
  wallBehavior: 'die' | 'wrap'
  selfCollision: boolean
  scoring: boolean
  growth: boolean
  /** 负面模式专用 */
  upgradePaths?: string[][]
  totalFoods?: number
  foodsPerLevel?: number
}

/** 自评选项 */
export type AssessOption = 1 | 2 | 3 | 4

/** 页面模块接口 */
export interface PageModule {
  render(container: HTMLElement): void
  destroy(): void
}
