// ============================================================
// 原创表情渲染引擎 v1.5
// 用 Canvas 2D 绘制治愈系表情，替代 emoji
// 径向渐变脸部 + 6 种眼睛 + 4 种嘴巴
// ============================================================

/** 表情类型 */
export type ExpressionType =
  | 'happy' | 'calm' | 'neutral' | 'sad'
  | 'anxious' | 'angry' | 'tired' | 'love'
  | 'relieved' | 'peaceful' | 'hopeful' | 'playful'
  | 'sleepy' | 'surprised' | 'embarrassed' | 'determined'
  | 'melting' | 'glowing' | 'sparkling' | 'bloom'

/** 表情渲染器接口 */
export interface ExpressionRenderer {
  draw(ctx: CanvasRenderingContext2D, expression: ExpressionType, x: number, y: number, size: number, alpha?: number): void
  drawById(ctx: CanvasRenderingContext2D, id: string, x: number, y: number, size: number, alpha?: number): void
}

/** 眼睛类型 */
type EyeDrawer = (ctx: CanvasRenderingContext2D, cx: number, cy: number, size: number) => void

/** 嘴巴类型 */
type MouthDrawer = (ctx: CanvasRenderingContext2D, cx: number, cy: number, size: number) => void

// ---- 颜色工具（使用共享模块） ----

import { hexToRgb, rgba } from '@/utils/color'

// ---- 脸部绘制 ----

function drawFace(ctx: CanvasRenderingContext2D, cx: number, cy: number, radius: number, baseColor: string, alpha: number) {
  const [r, g, b] = hexToRgb(baseColor)
  ctx.save()
  ctx.globalAlpha = alpha

  // 径向渐变脸部
  const grad = ctx.createRadialGradient(cx - radius * 0.2, cy - radius * 0.2, radius * 0.1, cx, cy, radius)
  grad.addColorStop(0, rgba(Math.min(r + 40, 255), Math.min(g + 40, 255), Math.min(b + 40, 255), 1))
  grad.addColorStop(0.7, baseColor)
  grad.addColorStop(1, rgba(Math.max(r - 20, 0), Math.max(g - 20, 0), Math.max(b - 20, 0), 0.9))

  ctx.beginPath()
  ctx.arc(cx, cy, radius, 0, Math.PI * 2)
  ctx.fillStyle = grad
  ctx.fill()

  // 极淡描边
  ctx.strokeStyle = rgba(Math.max(r - 30, 0), Math.max(g - 30, 0), Math.max(b - 30, 0), 0.15)
  ctx.lineWidth = 1
  ctx.stroke()

  ctx.restore()
}

// ---- 腮红 ----

function drawBlush(ctx: CanvasRenderingContext2D, cx: number, cy: number, radius: number, alpha: number) {
  ctx.save()
  ctx.globalAlpha = alpha * 0.25
  const blushColor = 'rgba(220, 160, 140, 1)'
  const blushRadius = radius * 0.18

  // 左腮红
  const lGrad = ctx.createRadialGradient(cx - radius * 0.45, cy + radius * 0.15, 0, cx - radius * 0.45, cy + radius * 0.15, blushRadius)
  lGrad.addColorStop(0, blushColor)
  lGrad.addColorStop(1, 'rgba(220, 160, 140, 0)')
  ctx.beginPath()
  ctx.arc(cx - radius * 0.45, cy + radius * 0.15, blushRadius, 0, Math.PI * 2)
  ctx.fillStyle = lGrad
  ctx.fill()

  // 右腮红
  const rGrad = ctx.createRadialGradient(cx + radius * 0.45, cy + radius * 0.15, 0, cx + radius * 0.45, cy + radius * 0.15, blushRadius)
  rGrad.addColorStop(0, blushColor)
  rGrad.addColorStop(1, 'rgba(220, 160, 140, 0)')
  ctx.beginPath()
  ctx.arc(cx + radius * 0.45, cy + radius * 0.15, blushRadius, 0, Math.PI * 2)
  ctx.fillStyle = rGrad
  ctx.fill()

  ctx.restore()
}

// ---- 6 种眼睛 ----

const eyeRound: EyeDrawer = (ctx, cx, cy, size) => {
  // 圆形眼睛（开心、平静）
  ctx.beginPath()
  ctx.arc(cx, cy, size * 0.12, 0, Math.PI * 2)
  ctx.fillStyle = '#3D3D3D'
  ctx.fill()
  // 高光
  ctx.beginPath()
  ctx.arc(cx + size * 0.04, cy - size * 0.04, size * 0.04, 0, Math.PI * 2)
  ctx.fillStyle = 'rgba(255,255,255,0.8)'
  ctx.fill()
}

const eyeHappy: EyeDrawer = (ctx, cx, cy, size) => {
  // 弯弯笑眼（^ ^）
  ctx.beginPath()
  ctx.arc(cx, cy + size * 0.02, size * 0.1, Math.PI, 0)
  ctx.strokeStyle = '#3D3D3D'
  ctx.lineWidth = size * 0.04
  ctx.lineCap = 'round'
  ctx.stroke()
}

const eyeSad: EyeDrawer = (ctx, cx, cy, size) => {
  // 下垂眼
  ctx.beginPath()
  ctx.arc(cx, cy, size * 0.1, 0, Math.PI * 2)
  ctx.fillStyle = '#3D3D3D'
  ctx.fill()
  // 眉毛（下垂）
  ctx.beginPath()
  ctx.moveTo(cx - size * 0.12, cy - size * 0.18)
  ctx.lineTo(cx + size * 0.08, cy - size * 0.14)
  ctx.strokeStyle = '#3D3D3D'
  ctx.lineWidth = size * 0.03
  ctx.lineCap = 'round'
  ctx.stroke()
}

const eyeAngry: EyeDrawer = (ctx, cx, cy, size) => {
  // 怒目
  ctx.beginPath()
  ctx.arc(cx, cy, size * 0.1, 0, Math.PI * 2)
  ctx.fillStyle = '#3D3D3D'
  ctx.fill()
  // 眉毛（倒竖）
  ctx.beginPath()
  ctx.moveTo(cx - size * 0.12, cy - size * 0.12)
  ctx.lineTo(cx + size * 0.08, cy - size * 0.2)
  ctx.strokeStyle = '#3D3D3D'
  ctx.lineWidth = size * 0.04
  ctx.lineCap = 'round'
  ctx.stroke()
}

const eyeSleepy: EyeDrawer = (ctx, cx, cy, size) => {
  // 眯缝眼
  ctx.beginPath()
  ctx.moveTo(cx - size * 0.1, cy)
  ctx.lineTo(cx + size * 0.1, cy)
  ctx.strokeStyle = '#3D3D3D'
  ctx.lineWidth = size * 0.04
  ctx.lineCap = 'round'
  ctx.stroke()
}

const eyeLove: EyeDrawer = (ctx, cx, cy, size) => {
  // 爱心眼（简化版小心形）
  const s = size * 0.08
  ctx.save()
  ctx.translate(cx, cy)
  ctx.beginPath()
  ctx.moveTo(0, s * 0.5)
  ctx.bezierCurveTo(-s, -s * 0.2, -s * 0.5, -s, 0, -s * 0.3)
  ctx.bezierCurveTo(s * 0.5, -s, s, -s * 0.2, 0, s * 0.5)
  ctx.fillStyle = '#E88B8B'
  ctx.fill()
  ctx.restore()
}

// ---- 4 种嘴巴 ----

const mouthSmile: MouthDrawer = (ctx, cx, cy, size) => {
  ctx.beginPath()
  ctx.arc(cx, cy - size * 0.02, size * 0.15, 0.1 * Math.PI, 0.9 * Math.PI)
  ctx.strokeStyle = '#3D3D3D'
  ctx.lineWidth = size * 0.035
  ctx.lineCap = 'round'
  ctx.stroke()
}

const mouthOpen: MouthDrawer = (ctx, cx, cy, size) => {
  ctx.beginPath()
  ctx.arc(cx, cy, size * 0.1, 0, Math.PI * 2)
  ctx.fillStyle = '#5A4040'
  ctx.fill()
}

const mouthFlat: MouthDrawer = (ctx, cx, cy, size) => {
  ctx.beginPath()
  ctx.moveTo(cx - size * 0.1, cy)
  ctx.lineTo(cx + size * 0.1, cy)
  ctx.strokeStyle = '#3D3D3D'
  ctx.lineWidth = size * 0.03
  ctx.lineCap = 'round'
  ctx.stroke()
}

const mouthSad: MouthDrawer = (ctx, cx, cy, size) => {
  ctx.beginPath()
  ctx.arc(cx, cy + size * 0.12, size * 0.12, 1.15 * Math.PI, 1.85 * Math.PI)
  ctx.strokeStyle = '#3D3D3D'
  ctx.lineWidth = size * 0.035
  ctx.lineCap = 'round'
  ctx.stroke()
}

// ---- 表情定义 ----

interface ExpressionDef {
  faceColor: string
  eyes: [EyeDrawer, EyeDrawer] // [左眼, 右眼]
  mouth: MouthDrawer
  blush: boolean
  extras?: (ctx: CanvasRenderingContext2D, cx: number, cy: number, size: number, alpha: number) => void
}

const EXPRESSIONS: Record<ExpressionType, ExpressionDef> = {
  happy: {
    faceColor: '#FFE4C4',
    eyes: [eyeHappy, eyeHappy],
    mouth: mouthSmile,
    blush: true,
  },
  calm: {
    faceColor: '#E8EDE6',
    eyes: [eyeSleepy, eyeSleepy],
    mouth: mouthSmile,
    blush: true,
  },
  neutral: {
    faceColor: '#F0E8D8',
    eyes: [eyeRound, eyeRound],
    mouth: mouthFlat,
    blush: false,
  },
  sad: {
    faceColor: '#D8D8E8',
    eyes: [eyeSad, eyeSad],
    mouth: mouthSad,
    blush: false,
  },
  anxious: {
    faceColor: '#E8D8C8',
    eyes: [eyeRound, eyeRound],
    mouth: mouthFlat,
    blush: false,
    extras: (ctx, cx, cy, size, alpha) => {
      // 汗滴
      ctx.save()
      ctx.globalAlpha = alpha * 0.5
      ctx.beginPath()
      ctx.moveTo(cx + size * 0.35, cy - size * 0.2)
      ctx.quadraticCurveTo(cx + size * 0.4, cy - size * 0.05, cx + size * 0.35, cy + size * 0.05)
      ctx.quadraticCurveTo(cx + size * 0.3, cy - size * 0.05, cx + size * 0.35, cy - size * 0.2)
      ctx.fillStyle = '#A8C8E8'
      ctx.fill()
      ctx.restore()
    },
  },
  angry: {
    faceColor: '#E8C8B8',
    eyes: [eyeAngry, eyeAngry],
    mouth: mouthFlat,
    blush: false,
  },
  tired: {
    faceColor: '#E0D8D0',
    eyes: [eyeSleepy, eyeSleepy],
    mouth: mouthFlat,
    blush: false,
  },
  love: {
    faceColor: '#FFE0E0',
    eyes: [eyeLove, eyeLove],
    mouth: mouthSmile,
    blush: true,
  },
  relieved: {
    faceColor: '#E8E8D8',
    eyes: [eyeSleepy, eyeSleepy],
    mouth: mouthSmile,
    blush: true,
  },
  peaceful: {
    faceColor: '#E0E8E0',
    eyes: [eyeHappy, eyeHappy],
    mouth: mouthSmile,
    blush: true,
  },
  hopeful: {
    faceColor: '#F0E8D0',
    eyes: [eyeRound, eyeRound],
    mouth: mouthSmile,
    blush: true,
  },
  playful: {
    faceColor: '#FFE8D0',
    eyes: [eyeHappy, eyeRound],
    mouth: mouthOpen,
    blush: true,
  },
  sleepy: {
    faceColor: '#E0D8E0',
    eyes: [eyeSleepy, eyeSleepy],
    mouth: mouthOpen,
    blush: false,
  },
  surprised: {
    faceColor: '#F0E0D0',
    eyes: [eyeRound, eyeRound],
    mouth: mouthOpen,
    blush: false,
  },
  embarrassed: {
    faceColor: '#F0D0C0',
    eyes: [eyeSad, eyeSad],
    mouth: mouthFlat,
    blush: true,
  },
  determined: {
    faceColor: '#E8D8C0',
    eyes: [eyeAngry, eyeAngry],
    mouth: mouthFlat,
    blush: false,
  },
  melting: {
    faceColor: '#E8E0D8',
    eyes: [eyeSleepy, eyeSleepy],
    mouth: mouthSmile,
    blush: true,
    extras: (ctx, cx, cy, size, alpha) => {
      // 融化效果：底部水滴
      ctx.save()
      ctx.globalAlpha = alpha * 0.3
      ctx.beginPath()
      ctx.ellipse(cx, cy + size * 0.8, size * 0.5, size * 0.15, 0, 0, Math.PI * 2)
      ctx.fillStyle = '#D8D0C8'
      ctx.fill()
      ctx.restore()
    },
  },
  glowing: {
    faceColor: '#FFF0D0',
    eyes: [eyeHappy, eyeHappy],
    mouth: mouthSmile,
    blush: true,
    extras: (ctx, cx, cy, size, alpha) => {
      // 光晕
      ctx.save()
      ctx.globalAlpha = alpha * 0.15
      const glow = ctx.createRadialGradient(cx, cy, size * 0.5, cx, cy, size * 1.2)
      glow.addColorStop(0, '#FFE888')
      glow.addColorStop(1, 'rgba(255, 232, 136, 0)')
      ctx.beginPath()
      ctx.arc(cx, cy, size * 1.2, 0, Math.PI * 2)
      ctx.fillStyle = glow
      ctx.fill()
      ctx.restore()
    },
  },
  sparkling: {
    faceColor: '#FFF4E0',
    eyes: [eyeRound, eyeRound],
    mouth: mouthSmile,
    blush: true,
    extras: (ctx, cx, cy, size, alpha) => {
      // 星星闪烁
      ctx.save()
      ctx.globalAlpha = alpha * 0.6
      ctx.fillStyle = '#FFD700'
      const drawStar = (sx: number, sy: number, s: number) => {
        ctx.beginPath()
        for (let i = 0; i < 4; i++) {
          const angle = (i / 4) * Math.PI * 2 - Math.PI / 2
          const ox = sx + Math.cos(angle) * s
          const oy = sy + Math.sin(angle) * s
          if (i === 0) ctx.moveTo(ox, oy)
          else ctx.lineTo(ox, oy)
          const midAngle = angle + Math.PI / 4
          const mx = sx + Math.cos(midAngle) * s * 0.3
          const my = sy + Math.sin(midAngle) * s * 0.3
          ctx.lineTo(mx, my)
        }
        ctx.closePath()
        ctx.fill()
      }
      drawStar(cx - size * 0.5, cy - size * 0.4, size * 0.08)
      drawStar(cx + size * 0.55, cy - size * 0.3, size * 0.06)
      drawStar(cx + size * 0.3, cy + size * 0.5, size * 0.05)
      ctx.restore()
    },
  },
  bloom: {
    faceColor: '#FFE8E0',
    eyes: [eyeHappy, eyeHappy],
    mouth: mouthSmile,
    blush: true,
    extras: (ctx, cx, cy, size, alpha) => {
      // 花朵绽放
      ctx.save()
      ctx.globalAlpha = alpha * 0.4
      const petalCount = 5
      for (let i = 0; i < petalCount; i++) {
        const angle = (i / petalCount) * Math.PI * 2 - Math.PI / 2
        const px = cx + Math.cos(angle) * size * 0.6
        const py = cy + Math.sin(angle) * size * 0.6
        ctx.beginPath()
        ctx.ellipse(px, py, size * 0.12, size * 0.08, angle, 0, Math.PI * 2)
        ctx.fillStyle = '#FFB8B8'
        ctx.fill()
      }
      ctx.restore()
    },
  },
}

// ---- Emoji ID → Expression 映射 ----

const EMOJI_TO_EXPRESSION: Record<string, ExpressionType> = {
  '😊': 'happy',
  '😍': 'love',
  '🥳': 'playful',
  '😢': 'sad',
  '😔': 'sad',
  '😐': 'neutral',
  '😶': 'neutral',
  '😡': 'angry',
  '😤': 'angry',
  '😰': 'anxious',
  '😨': 'anxious',
  '😌': 'relieved',
  '🙂': 'hopeful',
  '🥰': 'love',
  '🤪': 'playful',
  '😜': 'playful',
  '🥴': 'melting',
  '🤡': 'playful',
  '🧘': 'calm',
  '🍃': 'peaceful',
  '🌊': 'calm',
  '☁️': 'peaceful',
  '🌟': 'sparkling',
  '✨': 'sparkling',
  '💖': 'love',
  '🔥': 'determined',
  '🎉': 'playful',
  '🌱': 'hopeful',
  '🌸': 'bloom',
}

// ---- 主渲染器实现 ----

class CanvasExpressionRenderer implements ExpressionRenderer {
  // 表情缓存：key = `${expression}_${size}_${alpha}`
  private cache = new Map<string, HTMLCanvasElement>()
  private readonly MAX_CACHE_SIZE = 200

  /** 获取或创建缓存的表情画布 */
  private getCachedExpression(expression: ExpressionType, size: number, alpha: number): HTMLCanvasElement {
    const key = `${expression}_${size}_${alpha}`
    const cached = this.cache.get(key)
    if (cached) return cached

    // 缓存满时清理一半
    if (this.cache.size >= this.MAX_CACHE_SIZE) {
      const keys = Array.from(this.cache.keys())
      for (let i = 0; i < keys.length / 2; i++) {
        this.cache.delete(keys[i])
      }
    }

    // 创建离屏画布
    const offscreen = document.createElement('canvas')
    const padding = size * 0.3 // 为特效留空间
    offscreen.width = size + padding * 2
    offscreen.height = size + padding * 2
    const offCtx = offscreen.getContext('2d')!
    const cx = offscreen.width / 2
    const cy = offscreen.height / 2

    this.drawExpressionAt(offCtx, expression, cx, cy, size, alpha)
    this.cache.set(key, offscreen)
    return offscreen
  }

  /** 在指定位置绘制表情（无缓存，直接绘制） */
  private drawExpressionAt(
    ctx: CanvasRenderingContext2D,
    expression: ExpressionType,
    x: number,
    y: number,
    size: number,
    alpha: number
  ): void {
    const def = EXPRESSIONS[expression]
    if (!def) return

    const radius = size * 0.42
    const eyeOffsetX = radius * 0.35
    const eyeOffsetY = -radius * 0.15
    const mouthOffsetY = radius * 0.25

    // 脸部
    drawFace(ctx, x, y, radius, def.faceColor, alpha)

    // 腮红
    if (def.blush) {
      drawBlush(ctx, x, y, radius, alpha)
    }

    // 眼睛
    ctx.save()
    ctx.globalAlpha = alpha
    def.eyes[0](ctx, x - eyeOffsetX, y + eyeOffsetY, size)
    def.eyes[1](ctx, x + eyeOffsetX, y + eyeOffsetY, size)
    ctx.restore()

    // 嘴巴
    ctx.save()
    ctx.globalAlpha = alpha
    def.mouth(ctx, x, y + mouthOffsetY, size)
    ctx.restore()

    // 特效
    if (def.extras) {
      def.extras(ctx, x, y, size, alpha)
    }
  }

  draw(
    ctx: CanvasRenderingContext2D,
    expression: ExpressionType,
    x: number,
    y: number,
    size: number,
    alpha = 1
  ): void {
    const cached = this.getCachedExpression(expression, size, alpha)
    const padding = size * 0.3
    ctx.drawImage(cached, x - size / 2 - padding, y - size / 2 - padding)
  }

  drawById(
    ctx: CanvasRenderingContext2D,
    id: string,
    x: number,
    y: number,
    size: number,
    alpha = 1
  ): void {
    const expr = EMOJI_TO_EXPRESSION[id]
    if (expr) {
      this.draw(ctx, expr, x, y, size, alpha)
    } else {
      // Fallback: 绘制为中性表情
      this.draw(ctx, 'neutral', x, y, size, alpha)
    }
  }
}

/** 单例 */
export const expressionRenderer = new CanvasExpressionRenderer()

/** 获取表情类型（从 emoji 映射） */
export function getExpressionFromEmoji(emoji: string): ExpressionType {
  return EMOJI_TO_EXPRESSION[emoji] || 'neutral'
}
