// ============================================================
// 碰撞检测
// ============================================================

import type { Point } from '@/types'

/** 撞墙检测 */
export function checkWallCollision(
  head: Point,
  gridWidth: number,
  gridHeight: number,
  wallBehavior: 'die' | 'wrap'
): Point | null {
  if (head.x < 0 || head.x >= gridWidth || head.y < 0 || head.y >= gridHeight) {
    if (wallBehavior === 'wrap') {
      // 穿墙
      return {
        x: (head.x + gridWidth) % gridWidth,
        y: (head.y + gridHeight) % gridHeight,
      }
    }
    return null // 死亡
  }
  return head
}

/** 撞自己检测（Set-based O(1)） */
export function checkSelfCollision(head: Point, bodySet: Set<string>): boolean {
  return bodySet.has(`${head.x},${head.y}`)
}
