// ============================================================
// 声音选择弹窗
// ============================================================

import { t } from '@/i18n'
import { createElement, clearElement, getAppContainer } from '@/utils/dom'
import { stateMachine } from '@/state/machine'
import { GameState } from '@/types'
import { soundManager } from '@/services/sound-manager'
import { track } from '@/services/analytics'
import './sound-select.css'

export function renderSoundSelect(): void {
  const app = getAppContainer()
  clearElement(app)

  const page = createElement('main', { className: 'page sound-page', attrs: { role: 'main', 'aria-label': '声音设置页面' } })

  const question = createElement('p', {
    className: 'sound-question',
    textContent: t('soundQuestion'),
  })

  const buttons = createElement('div', {
    className: 'sound-buttons',
    attrs: { role: 'radiogroup', 'aria-label': t('soundQuestion') },
  })

  const soundOnBtn = createElement('button', {
    className: 'btn sound-btn active',
    textContent: t('soundOn'),
    attrs: { 'aria-label': t('soundOn'), role: 'radio', 'aria-checked': 'true' },
    onClick: () => {
      selectSound(true)
    },
  })

  const soundOffBtn = createElement('button', {
    className: 'btn sound-btn',
    textContent: t('soundOff'),
    attrs: { 'aria-label': t('soundOff'), role: 'radio', 'aria-checked': 'false' },
    onClick: () => {
      selectSound(false)
    },
  })

  buttons.append(soundOnBtn, soundOffBtn)
  page.append(question, buttons)
  app.appendChild(page)

  track('page_view', { page_name: 'sound_select' })
}

function selectSound(enabled: boolean): void {
  const ctx = stateMachine.context
  const mode = ctx.gameMode || 'positive'

  stateMachine.updateContext({ soundEnabled: enabled })
  soundManager.enabled = enabled

  if (enabled) {
    soundManager.preloadForMode(mode)
  }

  track('sound_toggle', { from: 'init', to: enabled ? 'on' : 'off' })
  stateMachine.transition(GameState.PLAYING)
}
