// ============================================================
// 音效管理器 (Howler.js)
// ============================================================

import { Howl, Howler } from 'howler'

type GameMode = 'positive' | 'negative'

interface SoundConfig {
  bgm?: string
  eatSfx?: string
  turnSfx?: string
  failSfx?: string
  healSfx?: string
}

const MODE_SOUNDS: Record<GameMode, SoundConfig> = {
  positive: {
    bgm: '/audio/bgm-positive.mp3',
    eatSfx: '/audio/sfx-eat.mp3',
    turnSfx: '/audio/sfx-turn.mp3',
    failSfx: '/audio/sfx-fail.mp3',
  },
  negative: {
    bgm: '/audio/bgm-negative-1.mp3',
    eatSfx: '/audio/sfx-eat.mp3',
    turnSfx: '/audio/sfx-turn.mp3',
    failSfx: '/audio/sfx-fail.mp3',
    healSfx: '/audio/sfx-heal.mp3',
  },
}

class SoundManager {
  private bgm: Howl | null = null
  private eatSfx: Howl | null = null
  private turnSfx: Howl | null = null
  private failSfx: Howl | null = null
  private healSfx: Howl | null = null
  private _enabled = true

  get enabled(): boolean {
    return this._enabled
  }

  set enabled(value: boolean) {
    this._enabled = value
    Howler.mute(!value)
  }

  /** 预加载当前模式音效 */
  preloadForMode(mode: GameMode): void {
    const config = MODE_SOUNDS[mode]

    if (config.bgm) {
      this.bgm = new Howl({
        src: [config.bgm],
        loop: true,
        volume: 0.5,
        preload: true,
      })
    }

    if (config.eatSfx) {
      this.eatSfx = new Howl({ src: [config.eatSfx], volume: 0.7 })
    }

    if (config.turnSfx) {
      this.turnSfx = new Howl({ src: [config.turnSfx], volume: 0.4 })
    }

    if (config.failSfx) {
      this.failSfx = new Howl({ src: [config.failSfx], volume: 0.6 })
    }

    if (config.healSfx) {
      this.healSfx = new Howl({ src: [config.healSfx], volume: 0.8 })
    }
  }

  /** 播放 BGM */
  playBgm(): void {
    if (this.bgm && this._enabled) {
      this.bgm.play()
    }
  }

  /** 停止 BGM */
  stopBgm(): void {
    if (this.bgm) {
      this.bgm.stop()
    }
  }

  /** 播放吃食物音效 */
  playEat(): void {
    if (this.eatSfx && this._enabled) {
      this.eatSfx.play()
    }
  }

  /** 播放转向音效 */
  playTurn(): void {
    if (this.turnSfx && this._enabled) {
      this.turnSfx.play()
    }
  }

  /** 播放失败音效 */
  playFail(): void {
    if (this.failSfx && this._enabled) {
      this.failSfx.play()
    }
  }

  /** 播放治愈音效 */
  playHeal(): void {
    if (this.healSfx && this._enabled) {
      this.healSfx.play()
    }
  }

  /** 停止所有音效 */
  stopAll(): void {
    Howler.stop()
  }

  /** 销毁 */
  destroy(): void {
    this.stopAll()
    this.bgm = null
    this.eatSfx = null
    this.turnSfx = null
    this.failSfx = null
    this.healSfx = null
  }
}

export const soundManager = new SoundManager()
