// ============================================================
// 蛇数据结构
// ============================================================

import type { Segment, Direction, Point } from '@/types'

export class Snake {
  segments: Segment[] = []
  direction: Direction = 'right'
  private nextDirection: Direction = 'right'
  private growPending = false

  constructor(startX: number, startY: number, length: number, emojis: string[]) {
    this.segments = []
    for (let i = 0; i < length; i++) {
      this.segments.push({
        x: startX - i,
        y: startY,
        emoji: emojis[i % emojis.length],
      })
    }
    this.direction = 'right'
    this.nextDirection = 'right'
  }

  /** 获取蛇头 */
  get head(): Segment {
    return this.segments[0]
  }

  /** 获取蛇身坐标集合（用于碰撞检测） */
  get bodySet(): Set<string> {
    const set = new Set<string>()
    // 从第 2 节开始（不含蛇头）
    for (let i = 1; i < this.segments.length; i++) {
      set.add(`${this.segments[i].x},${this.segments[i].y}`)
    }
    return set
  }

  /** 设置方向（防止 180 度转向） */
  setDirection(dir: Direction): boolean {
    const opposites: Record<Direction, Direction> = {
      up: 'down',
      down: 'up',
      left: 'right',
      right: 'left',
    }
    if (opposites[dir] === this.direction) return false
    this.nextDirection = dir
    return true
  }

  /** 移动一步 */
  move(): Point {
    this.direction = this.nextDirection

    const deltas: Record<Direction, Point> = {
      up: { x: 0, y: -1 },
      down: { x: 0, y: 1 },
      left: { x: -1, y: 0 },
      right: { x: 1, y: 0 },
    }

    const delta = deltas[this.direction]
    const newHead: Point = {
      x: this.head.x + delta.x,
      y: this.head.y + delta.y,
    }

    // 插入新蛇头
    this.segments.unshift({
      x: newHead.x,
      y: newHead.y,
      emoji: this.head.emoji,
    })

    // 如果不增长，移除尾部
    if (!this.growPending) {
      this.segments.pop()
    } else {
      this.growPending = false
    }

    return newHead
  }

  /** 增长（下次移动不移除尾部） */
  grow(): void {
    this.growPending = true
  }

  /** 更新蛇头表情 */
  setHeadEmoji(emoji: string): void {
    this.head.emoji = emoji
  }

  /** 更新所有节表情 */
  setAllEmojis(emojis: string[]): void {
    for (let i = 0; i < this.segments.length; i++) {
      this.segments[i].emoji = emojis[i % emojis.length]
    }
  }

  /** 从尾到头升级表情（负面模式转化） */
  upgradeFromTail(newEmojis: string[]): void {
    // 从尾部开始替换
    for (let i = this.segments.length - 1; i >= 0; i--) {
      const emojiIndex = this.segments.length - 1 - i
      if (emojiIndex < newEmojis.length) {
        this.segments[i].emoji = newEmojis[emojiIndex]
      }
    }
  }

  /** 获取长度 */
  get length(): number {
    return this.segments.length
  }
}
