// ============================================================
// 游戏页面（Canvas + HUD）
// ============================================================

import { t } from '@/i18n'
import { createElement, clearElement, getAppContainer } from '@/utils/dom'
import { stateMachine } from '@/state/machine'
import { GameState, type ModeConfig, type Direction } from '@/types'
import { GameLoop } from '@/engine/game-loop'
import { Snake } from '@/engine/snake'
import { FoodManager } from '@/engine/food'
import { GameRenderer } from '@/engine/renderer'
import { checkWallCollision, checkSelfCollision } from '@/engine/collision'
import { calculateSpeed } from '@/engine/difficulty'
import { createModeConfig } from '@/modes/mode-factory'
import { soundManager } from '@/services/sound-manager'
import { track } from '@/services/analytics'
import { CELL_SIZE, MAX_CANVAS_WIDTH, MAX_CANVAS_HEIGHT, HUD_AUTO_HIDE_DELAY } from '@/utils/constants'
import './game.css'

let gameLoop: GameLoop | null = null
let canvas: HTMLCanvasElement | null = null
let hudEl: HTMLElement | null = null
let scoreEl: HTMLElement | null = null
let healBarEl: HTMLElement | null = null
let pauseOverlayEl: HTMLElement | null = null
let pageEl: HTMLElement | null = null

// 游戏状态
let snake: Snake
let foodManager: FoodManager
let renderer: GameRenderer
let modeConfig: ModeConfig
let score = 0
let foodsEaten = 0
let healLevel = 0
let gameStartTime = 0
let paused = false
let hudHideTimer: ReturnType<typeof setTimeout> | null = null

export function renderGame(): void {
  const app = getAppContainer()
  clearElement(app)
  stopGame()

  const ctx = stateMachine.context
  const category = ctx.finalCategory || 'positive'
  modeConfig = createModeConfig(category)

  // 计算网格尺寸
  const canvasWidth = Math.min(MAX_CANVAS_WIDTH, window.innerWidth - 40)
  const canvasHeight = Math.min(MAX_CANVAS_HEIGHT, window.innerHeight - 120)
  const gridWidth = Math.floor(canvasWidth / CELL_SIZE)
  const gridHeight = Math.floor(canvasHeight / CELL_SIZE)

  // 创建页面
  const page = createElement('main', { className: 'page game-page', attrs: { role: 'main', 'aria-label': '游戏页面' } })

  // HUD
  hudEl = createElement('div', { className: 'game-hud', attrs: { 'aria-label': '游戏信息栏' } })
  const scoreSection = createElement('div', { className: 'hud-left' })
  scoreEl = createElement('span', { className: 'hud-score' })
  scoreSection.appendChild(scoreEl)

  const centerSection = createElement('div', { className: 'hud-center' })
  const modeLabel = createElement('span', {
    className: 'hud-mode',
    textContent: category === 'negative' ? t('modeNegative') : t('modePositive'),
  })
  centerSection.appendChild(modeLabel)

  const rightSection = createElement('div', { className: 'hud-right' })
  const soundToggle = createElement('button', {
    className: 'hud-sound-toggle',
    textContent: soundManager.enabled ? '🔊' : '🔇',
    onClick: () => {
      soundManager.enabled = !soundManager.enabled
      soundToggle.textContent = soundManager.enabled ? '🔊' : '🔇'
      track('sound_toggle', {
        from: soundManager.enabled ? 'off' : 'on',
        to: soundManager.enabled ? 'on' : 'off',
      })
    },
  })
  rightSection.appendChild(soundToggle)

  hudEl.append(scoreSection, centerSection, rightSection)

  // 治愈进度条（负面模式）
  if (category === 'negative') {
    healBarEl = createElement('div', { className: 'heal-bar-container' })
    const healLabel = createElement('span', { className: 'heal-label' })
    const healBar = createElement('div', { className: 'heal-bar' })
    const healFill = createElement('div', { className: 'heal-fill' })
    healBar.appendChild(healFill)
    healBarEl.append(healLabel, healBar)
    hudEl.appendChild(healBarEl)
  }

  // Canvas
  canvas = document.createElement('canvas')
  canvas.width = gridWidth * CELL_SIZE
  canvas.height = gridHeight * CELL_SIZE
  canvas.className = 'game-canvas'
  canvas.style.width = canvas.width + 'px'
  canvas.style.height = canvas.height + 'px'
  canvas.setAttribute('aria-label', '情绪贪吃蛇游戏画面')
  canvas.setAttribute('role', 'img')

  page.append(hudEl, canvas)
  app.appendChild(page)
  pageEl = page

  // 初始化游戏
  const canvasCtx = canvas.getContext('2d')!
  const bg = modeConfig.backgrounds[0]

  snake = new Snake(
    Math.floor(gridWidth / 2),
    Math.floor(gridHeight / 2),
    modeConfig.initialLength,
    modeConfig.snakeEmojis
  )

  foodManager = new FoodManager(gridWidth, gridHeight)
  foodManager.spawn(modeConfig.foodPools[0], snake.segments)

  renderer = new GameRenderer(
    canvasCtx,
    canvas.width,
    canvas.height,
    gridWidth,
    gridHeight,
    bg,
    modeConfig.gridColor
  )

  // 初始化状态
  score = 0
  foodsEaten = 0
  healLevel = 0
  paused = false
  gameStartTime = Date.now()

  updateHud()

  // 创建游戏循环
  gameLoop = new GameLoop(
    modeConfig.initialSpeed,
    update,
    render
  )

  // 键盘控制
  window.addEventListener('keydown', handleKeyDown)

  // 触控滑动控制（移动端）
  canvas.addEventListener('touchstart', handleTouchStart, { passive: true })
  canvas.addEventListener('touchend', handleTouchEnd, { passive: true })

  // HUD 自动隐藏
  resetHudHideTimer()
  if (hudEl) {
    hudEl.addEventListener('mouseenter', showHud)
    hudEl.addEventListener('touchstart', showHud, { passive: true })
  }

  // 播放 BGM
  if (soundManager.enabled) {
    soundManager.playBgm()
  }

  gameLoop.start()

  track('game_start', {
    mode: category === 'negative' ? 'negative' : 'positive',
    sound_enabled: soundManager.enabled,
  })
}

function update(_deltaTime: number): void {
  if (paused) return

  // 移动蛇
  const newHead = snake.move()

  // 撞墙检测
  const wallResult = checkWallCollision(
    newHead,
    foodManager.gridWidth,
    foodManager.gridHeight,
    modeConfig.wallBehavior
  )

  if (wallResult === null) {
    // 撞墙死亡
    onFail()
    return
  }

  // 如果是穿墙模式，更新蛇头位置
  if (wallResult.x !== newHead.x || wallResult.y !== newHead.y) {
    snake.head.x = wallResult.x
    snake.head.y = wallResult.y
  }

  // 撞自己检测
  if (modeConfig.selfCollision && checkSelfCollision(snake.head, snake.bodySet)) {
    onFail()
    return
  }

  // 吃食物检测
  if (foodManager.checkEat(snake.head.x, snake.head.y)) {
    onEat()
  }
}

function render(_interpolation: number): void {
  if (!canvas) return
  renderer.render(
    snake.segments,
    foodManager.currentFood,
    foodManager.currentEmoji,
    score,
    modeConfig.type === 'negative' ? foodsEaten / (modeConfig.totalFoods || 20) : undefined
  )
}

function onEat(): void {
  score++
  foodsEaten++
  snake.grow()
  soundManager.playEat()

  const currentPoolIndex = modeConfig.type === 'negative'
    ? Math.min(healLevel, (modeConfig.foodPools.length || 1) - 1)
    : 0

  foodManager.spawn(modeConfig.foodPools[currentPoolIndex], snake.segments)

  // 更新难度
  if (gameLoop) {
    const newSpeed = calculateSpeed(snake.length, modeConfig.initialSpeed, modeConfig.minSpeed)
    gameLoop.setStep(newSpeed)
  }

  // 负面模式：检查升级
  if (modeConfig.type === 'negative' && modeConfig.foodsPerLevel) {
    const newLevel = Math.min(
      Math.floor(foodsEaten / modeConfig.foodsPerLevel),
      (modeConfig.backgrounds?.length || 5) - 1
    )

    if (newLevel > healLevel) {
      healLevel = newLevel
      onLevelUp()
    }

    // 检查治愈完成
    if (foodsEaten >= (modeConfig.totalFoods || 20)) {
      onHealed()
      return
    }
  }

  updateHud()
  resetHudHideTimer() // 吃食物时短暂显示 HUD
  track('game_event', {
    mode: modeConfig.type,
    event_type: 'eat',
    score,
    heal_level: healLevel,
  })
}

function onLevelUp(): void {
  // 更新背景
  if (modeConfig.backgrounds && modeConfig.backgrounds[healLevel]) {
    renderer.setBackground(modeConfig.backgrounds[healLevel])
  }

  // 蛇身表情升级
  if (modeConfig.upgradePaths) {
    const pathIndex = Math.min(healLevel, modeConfig.upgradePaths.length - 1)
    const newEmojis = modeConfig.upgradePaths[pathIndex]
    // 从当前级别对应的表情集
    const levelEmojis = generateLevelEmojis(snake.length, newEmojis)
    snake.upgradeFromTail(levelEmojis)
  }

  track('game_event', { mode: 'negative', event_type: 'level_up', level: healLevel })
}

function generateLevelEmojis(length: number, path: string[]): string[] {
  const emojis: string[] = []
  const currentLevelEmoji = path[Math.min(healLevel, path.length - 1)]
  for (let i = 0; i < length; i++) {
    // 从头到尾渐变：头部是最高级，尾部可能还保留低级
    const ratio = i / Math.max(length - 1, 1)
    const pathIndex = Math.floor(ratio * (healLevel + 1))
    emojis.push(path[Math.min(pathIndex, path.length - 1)] || currentLevelEmoji)
  }
  return emojis
}

function onHealed(): void {
  stopGame()
  stateMachine.updateContext({
    score,
    healProgress: 100,
    healLevel,
    gameStartTime,
  })
  soundManager.playHeal()
  stateMachine.transition(GameState.HEALED)
}

function onFail(): void {
  stopGame()
  const failEmoji = modeConfig.failEmojis[Math.floor(Math.random() * modeConfig.failEmojis.length)]
  snake.setHeadEmoji(failEmoji)
  soundManager.playFail()

  // 失败过渡动画：先灰度渐隐，再跳转状态
  if (canvas) {
    canvas.classList.add('fail-transition')
  }

  const healProgress = modeConfig.type === 'negative'
    ? Math.round((foodsEaten / (modeConfig.totalFoods || 20)) * 100)
    : 0

  stateMachine.updateContext({
    score,
    healProgress,
    healLevel,
    gameStartTime,
  })

  track('game_end', {
    mode: modeConfig.type,
    end_type: 'fail',
    score,
    heal_progress: healProgress,
    duration_sec: Math.round((Date.now() - gameStartTime) / 1000),
  })

  // 延迟 600ms 等动画播完再跳转
  setTimeout(() => {
    stateMachine.transition(GameState.FAILED)
  }, 600)
}

function updateHud(): void {
  if (scoreEl) {
    if (modeConfig.scoring) {
      scoreEl.textContent = `🏆 ${t('score')}: ${score}`
    } else {
      scoreEl.textContent = `🏆 ${t('score')}: ${score}`
    }
  }

  if (healBarEl && modeConfig.type === 'negative') {
    const progress = Math.round((foodsEaten / (modeConfig.totalFoods || 20)) * 100)
    const label = healBarEl.querySelector('.heal-label')
    const fill = healBarEl.querySelector('.heal-fill')
    if (label) label.textContent = `${t('healProgress')} ${progress}%`
    if (fill) (fill as HTMLElement).style.width = `${progress}%`
  }
}

function handleKeyDown(e: KeyboardEvent): void {
  if (e.key === 'Escape') {
    togglePause()
    return
  }

  if (paused) return

  const keyMap: Record<string, Direction> = {
    ArrowUp: 'up',
    ArrowDown: 'down',
    ArrowLeft: 'left',
    ArrowRight: 'right',
    w: 'up',
    s: 'down',
    a: 'left',
    d: 'right',
    W: 'up',
    S: 'down',
    A: 'left',
    D: 'right',
  }

  const dir = keyMap[e.key]
  if (dir) {
    e.preventDefault()
    if (snake.setDirection(dir)) {
      soundManager.playTurn()
    }
  }
}

// ---- HUD 自动隐藏 ----

function resetHudHideTimer(): void {
  if (hudHideTimer) clearTimeout(hudHideTimer)
  showHud()
  hudHideTimer = setTimeout(() => {
    if (hudEl) hudEl.style.opacity = '0.15'
  }, HUD_AUTO_HIDE_DELAY)
}

function showHud(): void {
  if (hudEl) hudEl.style.opacity = '1'
  if (hudHideTimer) clearTimeout(hudHideTimer)
  hudHideTimer = setTimeout(() => {
    if (hudEl) hudEl.style.opacity = '0.15'
  }, HUD_AUTO_HIDE_DELAY)
}

// ---- 触控滑动控制 ----

let touchStartX = 0
let touchStartY = 0

function handleTouchStart(e: TouchEvent): void {
  const touch = e.touches[0]
  touchStartX = touch.clientX
  touchStartY = touch.clientY
  showHud()
}

function handleTouchEnd(e: TouchEvent): void {
  const touch = e.changedTouches[0]
  const dx = touch.clientX - touchStartX
  const dy = touch.clientY - touchStartY
  const absDx = Math.abs(dx)
  const absDy = Math.abs(dy)

  // 最小滑动距离 30px
  if (Math.max(absDx, absDy) < 30) return

  let dir: Direction
  if (absDx > absDy) {
    dir = dx > 0 ? 'right' : 'left'
  } else {
    dir = dy > 0 ? 'down' : 'up'
  }

  if (!paused && snake.setDirection(dir)) {
    soundManager.playTurn()
  }
}

// ---- 暂停 UI ----

function togglePause(): void {
  paused = !paused
  if (paused) {
    showPauseOverlay()
  } else {
    hidePauseOverlay()
  }
}

function showPauseOverlay(): void {
  if (pauseOverlayEl) return
  pauseOverlayEl = createElement('div', { className: 'pause-overlay' })
  const title = createElement('div', {
    className: 'pause-overlay-title',
    textContent: '⏸️ 暂停中',
  })
  const hint = createElement('div', {
    className: 'pause-overlay-hint',
    textContent: '按 ESC 继续',
  })
  pauseOverlayEl.append(title, hint)
  pageEl?.appendChild(pauseOverlayEl)
}

function hidePauseOverlay(): void {
  if (pauseOverlayEl && pageEl?.contains(pauseOverlayEl)) {
    pageEl.removeChild(pauseOverlayEl)
    pauseOverlayEl = null
  }
}

function stopGame(): void {
  if (gameLoop) {
    gameLoop.stop()
    gameLoop = null
  }
  soundManager.stopBgm()
  window.removeEventListener('keydown', handleKeyDown)
  if (canvas) {
    canvas.removeEventListener('touchstart', handleTouchStart)
    canvas.removeEventListener('touchend', handleTouchEnd)
  }
  if (hudHideTimer) {
    clearTimeout(hudHideTimer)
    hudHideTimer = null
  }
  if (hudEl) {
    hudEl.removeEventListener('mouseenter', showHud)
  }
  hidePauseOverlay()
}

export function destroyGame(): void {
  stopGame()
  canvas = null
  hudEl = null
  scoreEl = null
  healBarEl = null
  pauseOverlayEl = null
  pageEl = null
}
