// ============================================================

import type { EmotionResult, EmotionCategory } from '@/types'
import { AI_TIMEOUT, AI_PROCESS_LENGTH } from '@/utils/constants'
import { track } from './analytics'
import { getSessionId } from './storage'

/** AI Provider 接口 */
export interface AIProvider {
  judgeEmotion(text: string, lang: string): Promise<EmotionResult>
}

/** Qwen Provider 实现 */
class QwenProvider implements AIProvider {
  async judgeEmotion(text: string, lang: string): Promise<EmotionResult> {
    const startTime = Date.now()
    const truncatedText = text.slice(0, AI_PROCESS_LENGTH)

    const response = await fetch('/api/emotion', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: truncatedText, lang, session_id: getSessionId() }),
    })

    if (!response.ok) {
      throw new Error(`AI API error: ${response.status}`)
    }

    const data = await response.json()

    return {
      category: data.category as EmotionCategory,
      understanding: data.understanding as string,
      latency_ms: Date.now() - startTime,
      from_cache: data.from_cache ?? false,
    }
  }
}

/** 带超时的 AI 判断 */
export async function judgeEmotionWithTimeout(
  text: string,
  lang: string
): Promise<EmotionResult | null> {
  const provider = new QwenProvider()

  try {
    const result = await Promise.race([
      provider.judgeEmotion(text, lang),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error('timeout')), AI_TIMEOUT)
      ),
    ])

    track('ai_judgment', {
      ai_category: result.category,
      latency_ms: result.latency_ms,
      timeout: false,
      from_cache: result.from_cache,
    })

    return result
  } catch (err) {
    const isTimeout = err instanceof Error && err.message === 'timeout'

    track('ai_judgment', {
      ai_category: null,
      latency_ms: AI_TIMEOUT,
      timeout: isTimeout,
      from_cache: false,
    })

    return null
  }
}
