import {
  fetchStatsSummary,
  fetchDailyStats,
  saveAdminToken,
  getAdminToken,
  clearAdminToken,
  type StatsSummary,
  type DailyStats,
} from '@/services/stats'

let container: HTMLElement | null = null
let chartCanvas: HTMLCanvasElement | null = null
let chartCtx: CanvasRenderingContext2D | null = null
let currentDaily: DailyStats[] = []

/** 渲染统计面板 */
export function renderStats(): void {
  const app = document.getElementById('app')
  if (!app) return

  app.innerHTML = `
    <div class="stats-page">
      <header class="stats-header">
        <h1>📊 数据看板</h1>
        <p class="stats-subtitle">《蜕》情绪调节小游戏 · 访问情况统计</p>
      </header>

      <div id="stats-content">
        <div class="stats-loading">加载中...</div>
      </div>

      <footer class="stats-footer">
        <button class="stats-back-btn" id="stats-back">← 返回首页</button>
      </footer>
    </div>
  `

  container = document.getElementById('stats-content')

  // 返回按钮
  document.getElementById('stats-back')?.addEventListener('click', () => {
    window.location.hash = ''
    window.location.reload()
  })

  // 检查 token
  const token = getAdminToken()
  if (!token) {
    renderTokenInput()
  } else {
    loadStats(token)
  }
}

/** 渲染 Token 输入框 */
function renderTokenInput(): void {
  if (!container) return

  container.innerHTML = `
    <div class="stats-token-card">
      <div class="stats-token-icon">🔒</div>
      <h2>管理员登录</h2>
      <p class="stats-token-desc">请输入管理员 Token 查看统计数据</p>
      <input
        type="password"
        id="admin-token-input"
        class="stats-token-input"
        placeholder="输入 Admin Token"
      />
      <button class="stats-primary-btn" id="token-submit-btn">
        查看数据
      </button>
      <p class="stats-token-tip">数据仅保留最近 30 天</p>
    </div>
  `

  const input = document.getElementById('admin-token-input') as HTMLInputElement
  const btn = document.getElementById('token-submit-btn')

  const submit = () => {
    const token = input.value.trim()
    if (token) {
      saveAdminToken(token)
      loadStats(token)
    }
  }

  btn?.addEventListener('click', submit)
  input?.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') submit()
  })
  input?.focus()
}

/** 加载统计数据 */
async function loadStats(token: string): Promise<void> {
  if (!container) return

  try {
    const [summary, daily] = await Promise.all([
      fetchStatsSummary(token),
      fetchDailyStats(7, token),
    ])

    currentDaily = daily
    renderStatsContent(summary, daily)
  } catch (err) {
    console.error('Stats load error:', err)
    container.innerHTML = `
      <div class="stats-error">
        <div class="stats-error-icon">❌</div>
        <h2>加载失败</h2>
        <p>${err instanceof Error ? err.message : '未知错误'}</p>
        <button class="stats-outline-btn" id="retry-token-btn">
          重新输入 Token
        </button>
      </div>
    `
    document.getElementById('retry-token-btn')?.addEventListener('click', () => {
      clearAdminToken()
      renderTokenInput()
    })
  }
}

/** 渲染统计内容 */
function renderStatsContent(summary: StatsSummary, daily: DailyStats[]): void {
  if (!container) return

  container.innerHTML = `
    <!-- 总览卡片 -->
    <div class="stats-overview">
      <div class="stats-card">
        <div class="stats-card-icon">👁️</div>
        <div class="stats-card-info">
          <div class="stats-card-value">${formatNumber(summary.totalPV)}</div>
          <div class="stats-card-label">总访问量 (PV)</div>
        </div>
      </div>
      <div class="stats-card">
        <div class="stats-card-icon">👤</div>
        <div class="stats-card-info">
          <div class="stats-card-value">${formatNumber(summary.totalUV)}</div>
          <div class="stats-card-label">独立访客 (UV)</div>
        </div>
      </div>
      <div class="stats-card">
        <div class="stats-card-icon">🎮</div>
        <div class="stats-card-info">
          <div class="stats-card-value">${formatNumber(summary.totalGames)}</div>
          <div class="stats-card-label">游戏次数</div>
        </div>
      </div>
      <div class="stats-card">
        <div class="stats-card-icon">✨</div>
        <div class="stats-card-info">
          <div class="stats-card-value">${summary.healedRate}%</div>
          <div class="stats-card-label">治愈率</div>
        </div>
      </div>
    </div>

    <!-- 每日趋势 -->
    <div class="stats-section">
      <div class="stats-section-header">
        <h2>📈 每日趋势</h2>
        <div class="stats-day-tabs">
          <button class="stats-day-tab active" data-days="7">7天</button>
          <button class="stats-day-tab" data-days="14">14天</button>
          <button class="stats-day-tab" data-days="30">30天</button>
        </div>
      </div>
      <div class="stats-chart-card">
        <canvas id="daily-chart" height="200"></canvas>
      </div>
    </div>

    <!-- 分布数据 -->
    <div class="stats-distribution">
      <div class="stats-section">
        <h2>🌍 语言分布</h2>
        <div class="stats-bar-list">
          ${renderBarList(summary.languages)}
        </div>
      </div>

      <div class="stats-section">
        <h2>📄 页面访问</h2>
        <div class="stats-bar-list">
          ${renderBarList(summary.pages)}
        </div>
      </div>

      <div class="stats-section">
        <h2>💭 情绪分布</h2>
        <div class="stats-bar-list">
          ${renderBarList(summary.emotions)}
        </div>
      </div>
    </div>

    <div class="stats-meta">
      <span>数据周期：最近 30 天</span>
      <button class="stats-logout-btn" id="stats-logout">退出登录</button>
    </div>
  `

  // 初始化图表
  initChart()
  drawChart(daily)

  // 天数切换
  document.querySelectorAll('.stats-day-tab').forEach(tab => {
    tab.addEventListener('click', async (e) => {
      const days = parseInt((e.target as HTMLElement).dataset.days || '7', 10)

      // 更新 tab 样式
      document.querySelectorAll('.stats-day-tab').forEach(t =>
        t.classList.remove('active')
      )
      ;(e.target as HTMLElement).classList.add('active')

      // 加载新数据
      const token = getAdminToken()
      if (token) {
        const newDaily = await fetchDailyStats(days, token)
        currentDaily = newDaily
        drawChart(newDaily)
      }
    })
  })

  // 退出登录
  document.getElementById('stats-logout')?.addEventListener('click', () => {
    clearAdminToken()
    renderTokenInput()
  })
}

/** 渲染柱状图列表 */
function renderBarList(data: Record<string, number>): string {
  const entries = Object.entries(data).sort((a, b) => b[1] - a[1])
  if (entries.length === 0) {
    return '<div class="stats-empty">暂无数据</div>'
  }
  const max = entries[0][1]

  return entries
    .map(([label, value]) => {
      const percent = max > 0 ? (value / max) * 100 : 0
      return `
        <div class="stats-bar-item">
          <div class="stats-bar-label">${escapeHtml(label)}</div>
          <div class="stats-bar-track">
            <div class="stats-bar-fill" style="width: ${percent}%"></div>
          </div>
          <div class="stats-bar-value">${formatNumber(value)}</div>
        </div>
      `
    })
    .join('')
}

/** 初始化 Canvas 图表 */
function initChart(): void {
  chartCanvas = document.getElementById('daily-chart') as HTMLCanvasElement
  if (!chartCanvas) return

  const dpr = window.devicePixelRatio || 1
  const rect = chartCanvas.getBoundingClientRect()

  chartCanvas.width = rect.width * dpr
  chartCanvas.height = 200 * dpr

  chartCtx = chartCanvas.getContext('2d')
  if (chartCtx) {
    chartCtx.scale(dpr, dpr)
  }
}

/** 绘制趋势图 */
function drawChart(data: DailyStats[]): void {
  if (!chartCtx || !chartCanvas) return

  const width = chartCanvas.width / (window.devicePixelRatio || 1)
  const height = 200
  const padding = { top: 20, right: 20, bottom: 30, left: 40 }
  const chartW = width - padding.left - padding.right
  const chartH = height - padding.top - padding.bottom

  const ctx = chartCtx
  ctx.clearRect(0, 0, width, height)

  if (data.length === 0) {
    ctx.fillStyle = '#8A8A8A'
    ctx.font = '13px sans-serif'
    ctx.textAlign = 'center'
    ctx.fillText('暂无数据', width / 2, height / 2)
    return
  }

  // 计算最大值
  const maxPV = Math.max(...data.map(d => d.pv))
  const maxVal = Math.max(maxPV, 1)
  const yMax = Math.ceil(maxVal * 1.2) // 顶部留20%空间

  // 绘制网格线
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.06)'
  ctx.lineWidth = 1
  ctx.font = '11px sans-serif'
  ctx.fillStyle = '#8A8A8A'
  ctx.textAlign = 'right'

  const gridLines = 4
  for (let i = 0; i <= gridLines; i++) {
    const y = padding.top + (chartH / gridLines) * i
    ctx.beginPath()
    ctx.moveTo(padding.left, y)
    ctx.lineTo(padding.left + chartW, y)
    ctx.stroke()

    const val = Math.round(yMax - (yMax / gridLines) * i)
    ctx.fillText(String(val), padding.left - 8, y + 4)
  }

  // 绘制折线和面积
  const xStep = chartW / (data.length - 1 || 1)

  // 面积填充
  const gradient = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH)
  gradient.addColorStop(0, 'rgba(139, 168, 136, 0.3)')
  gradient.addColorStop(1, 'rgba(139, 168, 136, 0.02)')

  ctx.beginPath()
  data.forEach((d, i) => {
    const x = padding.left + xStep * i
    const y = padding.top + chartH - (d.pv / yMax) * chartH
    if (i === 0) {
      ctx.moveTo(x, y)
    } else {
      const prevX = padding.left + xStep * (i - 1)
      const prevY = padding.top + chartH - (data[i - 1].pv / yMax) * chartH
      const cpx = (prevX + x) / 2
      ctx.bezierCurveTo(cpx, prevY, cpx, y, x, y)
    }
  })
  ctx.lineTo(padding.left + chartW, padding.top + chartH)
  ctx.lineTo(padding.left, padding.top + chartH)
  ctx.closePath()
  ctx.fillStyle = gradient
  ctx.fill()

  // 折线
  ctx.beginPath()
  ctx.strokeStyle = '#8BA888'
  ctx.lineWidth = 2
  data.forEach((d, i) => {
    const x = padding.left + xStep * i
    const y = padding.top + chartH - (d.pv / yMax) * chartH
    if (i === 0) {
      ctx.moveTo(x, y)
    } else {
      const prevX = padding.left + xStep * (i - 1)
      const prevY = padding.top + chartH - (data[i - 1].pv / yMax) * chartH
      const cpx = (prevX + x) / 2
      ctx.bezierCurveTo(cpx, prevY, cpx, y, x, y)
    }
  })
  ctx.stroke()

  // 数据点
  data.forEach((d, i) => {
    const x = padding.left + xStep * i
    const y = padding.top + chartH - (d.pv / yMax) * chartH

    ctx.beginPath()
    ctx.arc(x, y, 3, 0, Math.PI * 2)
    ctx.fillStyle = '#8BA888'
    ctx.fill()
    ctx.strokeStyle = '#fff'
    ctx.lineWidth = 2
    ctx.stroke()
  })

  // X 轴标签
  ctx.fillStyle = '#8A8A8A'
  ctx.font = '11px sans-serif'
  ctx.textAlign = 'center'
  data.forEach((d, i) => {
    const x = padding.left + xStep * i
    const label = d.date.slice(5) // MM-DD
    // 只显示部分标签避免拥挤
    if (data.length <= 10 || i % Math.ceil(data.length / 7) === 0 || i === data.length - 1) {
      ctx.fillText(label, x, height - 10)
    }
  })
}

/** 数字格式化 */
function formatNumber(n: number): string {
  if (n >= 10000) {
    return (n / 10000).toFixed(1) + 'w'
  }
  if (n >= 1000) {
    return (n / 1000).toFixed(1) + 'k'
  }
  return String(n)
}

/** HTML 转义 */
function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

/** 销毁页面 */
export function destroyStats(): void {
  container = null
  chartCanvas = null
  chartCtx = null
  currentDaily = []
}
