// ============================================================
// 404 页面
// ============================================================

import { t } from '@/i18n'
import { createElement, clearElement, getAppContainer } from '@/utils/dom'
import { stateMachine } from '@/state/machine'
import { GameState } from '@/types'
import { track } from '@/services/analytics'
import './not-found.css'

export function renderNotFound(): void {
  const app = getAppContainer()
  clearElement(app)

  const page = createElement('main', {
    className: 'page not-found-page',
    attrs: { role: 'main', 'aria-label': '页面未找到' },
  })

  // 404 大图标
  const icon = createElement('div', {
    className: 'not-found-icon',
    textContent: '🍃',
  })

  // 标题
  const title = createElement('h1', {
    className: 'not-found-title',
    textContent: '404',
  })

  // 描述
  const desc = createElement('p', {
    className: 'not-found-desc',
    textContent: t('pageNotFound'),
  })

  // 返回按钮
  const backBtn = createElement('button', {
    className: 'btn not-found-btn',
    textContent: t('backToHome'),
    attrs: { 'aria-label': t('backToHome') },
    onClick: () => {
      stateMachine.transition(GameState.IDLE)
      // 清理 hash
      if (window.location.hash) {
        history.replaceState(null, '', window.location.pathname + window.location.search)
      }
    },
  })

  page.append(icon, title, desc, backBtn)
  app.appendChild(page)

  track('page_view', { page_name: '404' })
}
