// ============================================================
// 错误边界 — 全局异常捕获 + 用户友好提示 v1.6
// ============================================================

let initialized = false

/** 初始化全局错误边界 */
export function initErrorBoundary(): void {
  if (initialized) return
  initialized = true

  // 捕获未处理的同步错误
  window.addEventListener('error', (event: ErrorEvent) => {
    console.error('[ErrorBoundary] Uncaught error:', event.error)
    showErrorOverlay(event.error)
  })

  // 捕获未处理的 Promise rejection
  window.addEventListener('unhandledrejection', (event: PromiseRejectionEvent) => {
    console.error('[ErrorBoundary] Unhandled rejection:', event.reason)
    showErrorOverlay(event.reason)
  })
}

/** 显示错误覆盖层（仅在开发/测试模式或有错误时） */
function showErrorOverlay(error: unknown): void {
  // 避免重复显示
  if (document.getElementById('tui-error-overlay')) return

  const message = error instanceof Error ? error.message : String(error)
  const stack = error instanceof Error ? error.stack || '' : ''

  const overlay = document.createElement('div')
  overlay.id = 'tui-error-overlay'
  overlay.style.cssText = `
    position: fixed;
    inset: 0;
    z-index: 99999;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(250, 250, 247, 0.95);
    font-family: -apple-system, BlinkMacSystemFont, sans-serif;
    padding: 2rem;
    text-align: center;
  `

  overlay.innerHTML = `
    <div style="font-size: 3rem; margin-bottom: 1rem;">🌱</div>
    <h2 style="color: #2D2D2D; margin: 0 0 0.5rem; font-size: 1.25rem;">
      小蜕遇到了一点问题
    </h2>
    <p style="color: #666; margin: 0 0 1.5rem; font-size: 0.9rem;">
      请刷新页面重试，如果问题持续存在请联系开发者
    </p>
    <details style="max-width: 500px; text-align: left; margin-bottom: 1.5rem;">
      <summary style="cursor: pointer; color: #999; font-size: 0.8rem;">错误详情</summary>
      <pre style="background: #f0f0f0; padding: 1rem; border-radius: 8px;
        font-size: 0.75rem; overflow-x: auto; margin-top: 0.5rem;
        color: #c0392b; max-height: 200px; overflow-y: auto;">${escapeHtml(message)}\n${escapeHtml(stack.slice(0, 500))}</pre>
    </details>
    <button id="tui-error-reload" style="
      background: #8BA888;
      color: white;
      border: none;
      padding: 0.75rem 2rem;
      border-radius: 24px;
      font-size: 1rem;
      cursor: pointer;
    ">刷新页面</button>
  `

  document.body.appendChild(overlay)

  overlay.querySelector('#tui-error-reload')?.addEventListener('click', () => {
    window.location.reload()
  })
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}
