// ============================================================
// Canvas 渲染器 v1.5
// 径向渐变背景 + 暗角 + 蛇身豆式设计 + 食物浮动动画
// ============================================================

import type { Segment, Point, GradientColors } from '@/types'
import { emojiRenderer } from '@/services/emoji-renderer'
import { CELL_SIZE, CALM_MODE_STORAGE_KEY } from '@/utils/constants'
import { lightenColor } from '@/utils/color'

export class GameRenderer {
  private ctx: CanvasRenderingContext2D
  private canvasWidth: number
  private canvasHeight: number
  private gridWidth: number
  private gridHeight: number
  private bgFrom: string
  private bgTo: string
  private gridColor: string
  private frameCount = 0
  private calmMode = false

  constructor(
    ctx: CanvasRenderingContext2D,
    canvasWidth: number,
    canvasHeight: number,
    gridWidth: number,
    gridHeight: number,
    bg: GradientColors,
    gridColor: string
  ) {
    this.ctx = ctx
    this.canvasWidth = canvasWidth
    this.canvasHeight = canvasHeight
    this.gridWidth = gridWidth
    this.gridHeight = gridHeight
    this.bgFrom = bg.from
    this.bgTo = bg.to
    this.gridColor = gridColor

    // 检测平静模式：用户设置 或 系统 prefers-reduced-motion
    this.calmMode = localStorage.getItem(CALM_MODE_STORAGE_KEY) === 'true'
      || window.matchMedia('(prefers-reduced-motion: reduce)').matches
  }

  /** 更新背景颜色（用于负面模式渐变） */
  setBackground(bg: GradientColors): void {
    this.bgFrom = bg.from
    this.bgTo = bg.to
  }

  /** 渲染一帧 */
  render(
    snake: Segment[],
    food: Point | null,
    foodEmoji: string,
    _score: number,
    _healProgress?: number
  ): void {
    this.frameCount++

    // 径向渐变背景
    this.drawBackground()

    // 极淡网格
    this.drawGrid()

    // 食物（浮动 + 光晕）
    if (food) {
      this.drawFood(food, foodEmoji)
    }

    // 蛇身（豆式设计）
    this.drawSnake(snake)

    // 暗角
    this.drawVignette()
  }

  // ---- 径向渐变背景（中心亮，边缘略暗） ----
  private drawBackground(): void {
    const cx = this.canvasWidth / 2
    const cy = this.canvasHeight / 2
    const maxR = Math.sqrt(cx * cx + cy * cy)

    const grad = this.ctx.createRadialGradient(cx, cy, 0, cx, cy, maxR)
    grad.addColorStop(0, lightenColor(this.bgFrom, 0.15))
    grad.addColorStop(0.5, this.bgFrom)
    grad.addColorStop(1, this.bgTo)

    this.ctx.fillStyle = grad
    this.ctx.fillRect(0, 0, this.canvasWidth, this.canvasHeight)
  }

  // ---- 极淡网格 ----
  private drawGrid(): void {
    this.ctx.strokeStyle = this.gridColor
    this.ctx.lineWidth = 0.5
    this.ctx.globalAlpha = 0.3

    for (let x = 0; x <= this.gridWidth; x++) {
      this.ctx.beginPath()
      this.ctx.moveTo(x * CELL_SIZE, 0)
      this.ctx.lineTo(x * CELL_SIZE, this.gridHeight * CELL_SIZE)
      this.ctx.stroke()
    }
    for (let y = 0; y <= this.gridHeight; y++) {
      this.ctx.beginPath()
      this.ctx.moveTo(0, y * CELL_SIZE)
      this.ctx.lineTo(this.gridWidth * CELL_SIZE, y * CELL_SIZE)
      this.ctx.stroke()
    }
    this.ctx.globalAlpha = 1
  }

  // ---- 食物（浮动动画 + 脉冲光晕） ----
  private drawFood(pos: Point, emoji: string): void {
    const x = pos.x * CELL_SIZE + CELL_SIZE / 2
    const y = pos.y * CELL_SIZE + CELL_SIZE / 2

    // 平静模式下禁用浮动和光晕动画
    if (this.calmMode) {
      emojiRenderer.draw(this.ctx, emoji, x, y, CELL_SIZE * 0.7)
      return
    }

    // 浮动偏移
    const floatOffset = Math.sin(this.frameCount * 0.05) * 2
    const drawY = y + floatOffset

    // 脉冲光晕
    const pulseScale = 1 + Math.sin(this.frameCount * 0.08) * 0.1
    const glowRadius = CELL_SIZE * 0.5 * pulseScale
    const glow = this.ctx.createRadialGradient(x, drawY, 0, x, drawY, glowRadius)
    glow.addColorStop(0, 'rgba(255, 255, 200, 0.3)')
    glow.addColorStop(1, 'rgba(255, 255, 200, 0)')
    this.ctx.beginPath()
    this.ctx.arc(x, drawY, glowRadius, 0, Math.PI * 2)
    this.ctx.fillStyle = glow
    this.ctx.fill()

    // 绘制表情
    emojiRenderer.draw(this.ctx, emoji, x, drawY, CELL_SIZE * 0.7)
  }

  // ---- 蛇身（豆式设计：头部大，身体渐变缩小） ----
  private drawSnake(segments: Segment[]): void {
    const len = segments.length

    for (let i = len - 1; i >= 0; i--) {
      const seg = segments[i]
      const x = seg.x * CELL_SIZE + CELL_SIZE / 2
      const y = seg.y * CELL_SIZE + CELL_SIZE / 2

      // 头部最大，尾部最小
      const ratio = i / Math.max(len - 1, 1)
      const sizeMultiplier = 1 - ratio * 0.3
      const drawSize = CELL_SIZE * 0.85 * sizeMultiplier

      // 头部微弹动画（平静模式下禁用）
      let scale = 1
      if (i === 0 && !this.calmMode) {
        scale = 1 + Math.sin(this.frameCount * 0.1) * 0.03
      }

      // 尾部略透明
      const alpha = 1 - ratio * 0.2

      this.ctx.save()
      this.ctx.globalAlpha = alpha
      this.ctx.translate(x, y)
      this.ctx.scale(scale, scale)
      this.ctx.translate(-x, -y)

      emojiRenderer.draw(this.ctx, seg.emoji, x, y, drawSize)

      this.ctx.restore()
    }
  }

  // ---- 暗角效果（边缘微暗，增加沉浸感） ----
  private drawVignette(): void {
    const cx = this.canvasWidth / 2
    const cy = this.canvasHeight / 2
    const maxR = Math.sqrt(cx * cx + cy * cy)

    const vignette = this.ctx.createRadialGradient(cx, cy, maxR * 0.6, cx, cy, maxR)
    vignette.addColorStop(0, 'rgba(0, 0, 0, 0)')
    vignette.addColorStop(1, 'rgba(0, 0, 0, 0.12)')

    this.ctx.fillStyle = vignette
    this.ctx.fillRect(0, 0, this.canvasWidth, this.canvasHeight)
  }

}
