// ============================================================
// 入口文件 — v1.7 支持统计面板
// ============================================================

import { initErrorBoundary } from '@/utils/error-boundary'
import { initI18n } from '@/i18n'
import { initApp } from '@/app'
import { renderStats } from '@/pages/stats'
import './style.css'

// 初始化错误边界（最先注册，捕获所有后续错误）
initErrorBoundary()

// 初始化 i18n
initI18n()

// 检查是否访问统计面板
const hash = window.location.hash
if (hash === '#/stats' || hash === '#stats') {
  renderStats()
} else {
  // 启动正常 App
  initApp()
}
