// ============================================================
// 轻量状态机
// ============================================================

import { GameState, type GameContext } from '@/types'

/** 状态转换白名单 */
const TRANSITIONS: Record<GameState, GameState[]> = {
  [GameState.IDLE]: [GameState.LOADING],
  [GameState.LOADING]: [GameState.CONFIRM],
  [GameState.CONFIRM]: [GameState.SOUND],
  [GameState.SOUND]: [GameState.PLAYING],
  [GameState.PLAYING]: [GameState.PAUSED, GameState.FAILED, GameState.HEALED],
  [GameState.PAUSED]: [GameState.PLAYING, GameState.FAILED],
  [GameState.FAILED]: [GameState.ASSESS],
  [GameState.HEALED]: [GameState.ASSESS],
  [GameState.ASSESS]: [GameState.IDLE],
}

type StateListener = (state: GameState, prev: GameState, ctx: GameContext) => void

class StateMachine {
  private _state: GameState = GameState.IDLE
  private _context: GameContext = {}
  private _listeners: StateListener[] = []

  get state(): GameState {
    return this._state
  }

  get context(): GameContext {
    return this._context
  }

  /** 注册状态变化监听器 */
  on(listener: StateListener): () => void {
    this._listeners.push(listener)
    return () => {
      this._listeners = this._listeners.filter(l => l !== listener)
    }
  }

  /** 尝试状态转换 */
  transition(to: GameState): boolean {
    const allowed = TRANSITIONS[this._state]
    if (!allowed.includes(to)) {
      console.warn(`[StateMachine] Invalid transition: ${this._state} → ${to}`)
      return false
    }
    const prev = this._state
    this._state = to
    for (const listener of this._listeners) {
      listener(to, prev, this._context)
    }
    return true
  }

  /** 强制设置状态（用于特殊场景，如从游戏内直接回首页） */
  forceTransition(to: GameState): void {
    const prev = this._state
    this._state = to
    for (const listener of this._listeners) {
      listener(to, prev, this._context)
    }
  }

  /** 更新上下文 */
  updateContext(patch: Partial<GameContext>): void {
    this._context = { ...this._context, ...patch }
  }

  /** 重置（回到首页） */
  reset(): void {
    this._context = {}
    if (this._state !== GameState.IDLE) {
      this.forceTransition(GameState.IDLE)
    }
  }
}

export const stateMachine = new StateMachine()
